                + "<OFD Version=\"1.2\" DocType=\"OFD\">"
                + "<DocBody><DocInfo><DocID>id-0</DocID></DocInfo>"
                + "<DocRoot>Doc_0/Document.xml</DocRoot>"
                + "<Signatures>" + SIG_LOC_ABS + "</Signatures></DocBody>"
                + "<DocBody><DocInfo><DocID>id-1</DocID></DocInfo>"
                + "<DocRoot>Doc_1/Document.xml</DocRoot>"
                + "<Signatures>/Doc_1/Signs/Signatures.xml</Signatures></DocBody>"
                + "</OFD>";
