public static int[] rgb(ResourceManage resMgt, CT_Color ctColor) {
        if (ctColor == null) {
            return new int[]{0, 0, 0};
        }
        ST_Array colorValues = ctColor.getValue();
        final Integer index = ctColor.getIndex();
        if (colorValues == null && index == null) {
            // Index 和  colorValues 都不出现式，该颜色个通道的值全部为0
            return new int[]{0, 0, 0};
        }

        CT_ColorSpace cs = null;
        ST_RefID colorSpaceId = ctColor.getColorSpace();
        if (colorSpaceId != null && resMgt != null) {
            // 尝试从资源管理器中获取颜色空间
            cs = resMgt.getColorSpace(colorSpaceId.toString());
        }
        if (cs == null) {
            // 颜色空间不存在时，采用RGB作为默认颜色空间
            if (colorValues == null) {
                return new int[]{0, 0, 0};
            }
            cs = new CT_ColorSpace(OFDColorSpaceType.RGB);
        }

        // 颜色索引，存在时从索引位置获取颜色数值
        if (index != null) {
            final Palette palette = cs.getPalette();
            if (palette == null) {
                return new int[]{0, 0, 0};
            }
            final List<CV> cVs = palette.getCVs();
            colorValues = cVs.get(index).getColor();
        }
        if (colorValues == null) return null;
        int[] color = new int[colorValues.size()];
        for (int i = 0; i < colorValues.size(); i++) {
            String s = colorValues.getArray().get(i);
            if (s.startsWith("#")) {
                color[i] = Integer.parseInt(s.replaceAll("#", ""), 16);
            } else if (s.indexOf('.') != -1) {
                color[i] = (int) Float.parseFloat(s);
            } else {
                color[i] = Integer.parseInt(s);
            }
        }
        // 根据颜色空间类型，转换颜色为RGB
        switch (cs.getType()) {
            case RGB:
                return color;
            case CMYK:
                return cmykToRgb(color[0], color[1], color[2], color[3]);
            case GRAY:
                return new int[]{color[0], color[0], color[0]};
        }
        return new int[]{0, 0, 0};
    }

