    private String write(String fileName, byte[] content) throws Exception {
        Path file = tempDir.resolve(fileName);
        Files.write(file, content);
        return file.toAbsolutePath().toString();
    }

    private static Map<String, byte[]> fontTables(String psName, String familyName) {
        Map<String, byte[]> tables = new LinkedHashMap<>();
        tables.put("glyf", new byte[0]);
        tables.put("head", headTable());
        tables.put("loca", new byte[]{0, 0});
        tables.put("maxp", maxpTable(0));
        tables.put("name", nameTable(psName, familyName));
        return tables;
    }

    private static byte[] headTable() {
        byte[] table = new byte[54];
        putInt(table, 0, 0x00010000); // version
        putInt(table, 12, 0x5F0F3CF5); // magic number (not validated by the parser)
        putShort(table, 18, 1000); // unitsPerEm
        putShort(table, 50, 0); // indexToLocFormat: short offsets
        return table;
    }

    private static byte[] maxpTable(int numGlyphs) {
        byte[] table = new byte[6];
        putInt(table, 0, 0x00010000); // version
        putShort(table, 4, numGlyphs);
        return table;
    }

    private static byte[] nameTable(String psName, String familyName) {
        int[] nameIds = {1, 2, 6}; // family, subfamily, PostScript name
        String[] values = {familyName, "Regular", psName};
        List<byte[]> strings = new ArrayList<>();
        for (String value : values) {
            strings.add(value.getBytes(StandardCharsets.UTF_16BE));
        }

        int count = nameIds.length;
        int stringStorageOffset = 6 + count * 12;
        int totalLength = stringStorageOffset;
        for (byte[] string : strings) {
            totalLength += string.length;
        }

        byte[] table = new byte[totalLength];
        putShort(table, 0, 0); // format
        putShort(table, 2, count);
        putShort(table, 4, stringStorageOffset);

        int recordPosition = 6;
        int stringPosition = stringStorageOffset;
        for (int i = 0; i < count; i++) {
            byte[] string = strings.get(i);
            // Windows platform, Unicode BMP encoding, en-US language.
            putShort(table, recordPosition, 3);
            putShort(table, recordPosition + 2, 1);
            putShort(table, recordPosition + 4, 0x0409);
            putShort(table, recordPosition + 6, nameIds[i]);
            putShort(table, recordPosition + 8, string.length);
            putShort(table, recordPosition + 10, stringPosition - stringStorageOffset);
            System.arraycopy(string, 0, table, stringPosition, string.length);
            recordPosition += 12;
            stringPosition += string.length;
        }
        return table;
    }

    private static byte[] buildSfnt(Map<String, byte[]> tables) {
        List<String> tags = sortedTags(tables);
        int numTables = tags.size();
        int dataStart = align4(12 + numTables * 16);

        Map<String, Integer> offsets = new LinkedHashMap<>();
        int position = dataStart;
        for (String tag : tags) {
            offsets.put(tag, position);
            position = align4(position + tables.get(tag).length);
        }

        byte[] file = new byte[position];
        writeSfntDirectory(file, 0, tags, offsets, tables);
        copyTableData(file, tags, offsets, tables);
        return file;
    }

    @SafeVarargs
    private static byte[] buildTtc(Map<String, byte[]>... fonts) {
        int numFonts = fonts.length;
        int numTables = fonts[0].size();
        int headerSize = 12 + numFonts * 4;
        int directorySize = 12 + numTables * 16;

        List<Map<String, Integer>> allOffsets = new ArrayList<>();
        int position = align4(headerSize + numFonts * directorySize);
        for (Map<String, byte[]> tables : fonts) {
            List<String> tags = sortedTags(tables);
            Map<String, Integer> offsets = new LinkedHashMap<>();
            for (String tag : tags) {
                offsets.put(tag, position);
                position = align4(position + tables.get(tag).length);
            }
            allOffsets.add(offsets);
        }

        byte[] file = new byte[position];
        file[0] = 't';
        file[1] = 't';
        file[2] = 'c';
        file[3] = 'f';
        putInt(file, 4, 0x00010000); // version 1.0
        putInt(file, 8, numFonts);

        for (int i = 0; i < numFonts; i++) {
            int directoryOffset = headerSize + i * directorySize;
            putInt(file, 12 + i * 4, directoryOffset);

            Map<String, byte[]> tables = fonts[i];
            List<String> tags = sortedTags(tables);
            writeSfntDirectory(file, directoryOffset, tags, allOffsets.get(i), tables);
            copyTableData(file, tags, allOffsets.get(i), tables);
        }
        return file;
    }

    private static void writeSfntDirectory(byte[] file, int base, List<String> tags,
                                          Map<String, Integer> offsets,
                                          Map<String, byte[]> tables) {
        int numTables = tags.size();
        putInt(file, base, 0x00010000); // sfnt version
        putShort(file, base + 4, numTables);

        int maxPowerOfTwo = 1;
        int entrySelector = 0;
        while (maxPowerOfTwo * 2 <= numTables) {
            maxPowerOfTwo *= 2;
            entrySelector++;
        }
        int searchRange = maxPowerOfTwo * 16;
        putShort(file, base + 6, searchRange);
        putShort(file, base + 8, entrySelector);
        putShort(file, base + 10, numTables * 16 - searchRange);

        int recordPosition = base + 12;
        for (String tag : tags) {
            byte[] tagBytes = tag.getBytes(StandardCharsets.US_ASCII);
            System.arraycopy(tagBytes, 0, file, recordPosition, 4);
            putInt(file, recordPosition + 4, 0); // checksum (not validated)
            putInt(file, recordPosition + 8, offsets.get(tag));
            putInt(file, recordPosition + 12, tables.get(tag).length);
            recordPosition += 16;
        }
    }

    private static void copyTableData(byte[] file, List<String> tags,
                                      Map<String, Integer> offsets,
                                      Map<String, byte[]> tables) {
        for (String tag : tags) {
            byte[] data = tables.get(tag);
            System.arraycopy(data, 0, file, offsets.get(tag), data.length);
        }
    }

    private static List<String> sortedTags(Map<String, byte[]> tables) {
        List<String> tags = new ArrayList<>(tables.keySet());
        Collections.sort(tags);
        return tags;
    }

    private static int align4(int value) {
        return (value + 3) & ~3;
    }

    private static void putShort(byte[] target, int offset, int value) {
        target[offset] = (byte) ((value >>> 8) & 0xFF);
        target[offset + 1] = (byte) (value & 0xFF);
    }

    private static void putInt(byte[] target, int offset, int value) {
        target[offset] = (byte) ((value >>> 24) & 0xFF);
        target[offset + 1] = (byte) ((value >>> 16) & 0xFF);
        target[offset + 2] = (byte) ((value >>> 8) & 0xFF);
        target[offset + 3] = (byte) (value & 0xFF);
    }
}

