    /** A logical name record: fixed header values plus the raw storage bytes of its string. */
    private static final class Spec {
        final int platform;
        final int encoding;
        final int language;
        final int nameId;
        final byte[] bytes;

        Spec(int platform, int encoding, int language, int nameId, byte[] bytes) {
            this.platform = platform;
            this.encoding = encoding;
            this.language = language;
            this.nameId = nameId;
            this.bytes = bytes;
