    private static byte[] buildTable(int formatSelector, List<Spec> specs, int[] explicitOffsets) {
        int n = specs.size();
        int storageStart = 6 + n * 12;

        ByteArrayOutputStream storage = new ByteArrayOutputStream();
        int[] offsets = new int[n];
        for (int i = 0; i < n; i++) {
            offsets[i] = storage.size();
            byte[] b = specs.get(i).bytes;
            storage.write(b, 0, b.length);
        }

        ByteArrayOutputStream out = new ByteArrayOutputStream();
        writeU16(out, formatSelector);
        writeU16(out, n);
        writeU16(out, storageStart);
        for (int i = 0; i < n; i++) {
            Spec s = specs.get(i);
            writeU16(out, s.platform);
            writeU16(out, s.encoding);
            writeU16(out, s.language);
            writeU16(out, s.nameId);
            writeU16(out, s.bytes.length);
            writeU16(out, explicitOffsets == null ? offsets[i] : explicitOffsets[i]);
