    void readParsesAllNameRecordHeaderFields() throws IOException {
        List<Spec> specs = new ArrayList<>();
        specs.add(new Spec(NameRecord.PLATFORM_MACINTOSH, NameRecord.ENCODING_MACINTOSH_ROMAN,
