            ByteArrayOutputStream out = new ByteArrayOutputStream();
            byte[] buf = new byte[4096];
            int read;
            while ((read = in.read(buf)) != -1) {
                out.write(buf, 0, read);
            }
            return out.toByteArray();
        }
    }

    /**
     * head + maxp 两张表的组合，numGlyphs 固定为 2，loca 由调用方补充。
     */
    private static Map<String, byte[]> minimalTableSet(int unitsPerEm, int indexToLocFormat) {
        Map<String, byte[]> tables = new LinkedHashMap<>();
        tables.put("head", head(unitsPerEm, indexToLocFormat));
        tables.put("maxp", maxp(2));
        // numGlyphs = 2 -> 3 个偏移量，全部为 0（两个空字形）
        if (indexToLocFormat == 0) {
            tables.put("loca", cat(u16(0), u16(0), u16(0)));
        } else {
            tables.put("loca", cat(u32(0L), u32(0L), u32(0L)));
        }
        tables.put("glyf", new byte[0]);
        return tables;
    }

    /**
     * 按 OpenType 规范拼装 sfnt 字体数据。
     */
    private static byte[] buildTtf(Map<String, byte[]> tables) {
        List<String> tags = new ArrayList<>(tables.keySet());
        Collections.sort(tags);
        int numTables = tags.size();
        int entrySelector = 0;
        while ((1 << (entrySelector + 1)) <= numTables) {
            entrySelector++;
        }
        int searchRange = (1 << entrySelector) * 16;
        int rangeShift = numTables * 16 - searchRange;

        int dirSize = 12 + numTables * 16;
        int[] offsets = new int[numTables];
        int total = dirSize;
        for (int i = 0; i < numTables; i++) {
            total = (total + 3) & ~3;
            offsets[i] = total;
            total += tables.get(tags.get(i)).length;
        }
        byte[] out = new byte[total];
        System.arraycopy(u32(0x00010000L), 0, out, 0, 4);
        System.arraycopy(u16(numTables), 0, out, 4, 2);
        System.arraycopy(u16(searchRange), 0, out, 6, 2);
        System.arraycopy(u16(entrySelector), 0, out, 8, 2);
        System.arraycopy(u16(rangeShift), 0, out, 10, 2);
        int pos = 12;
        for (int i = 0; i < numTables; i++) {
            String tag = tags.get(i);
            byte[] data = tables.get(tag);
            System.arraycopy(tag.getBytes(StandardCharsets.ISO_8859_1), 0, out, pos, 4);
            System.arraycopy(u32(0L), 0, out, pos + 4, 4);          // checkSum
            System.arraycopy(u32(offsets[i]), 0, out, pos + 8, 4);  // offset
            System.arraycopy(u32(data.length), 0, out, pos + 12, 4);// length
            pos += 16;
        }
        for (int i = 0; i < numTables; i++) {
            byte[] data = tables.get(tags.get(i));
            System.arraycopy(data, 0, out, offsets[i], data.length);
        }
        return out;
    }

    /**
     * 54 字节的 head 表：offset 18 为 unitsPerEm，offset 50 为 indexToLocFormat。
     */
    private static byte[] head(int unitsPerEm, int indexToLocFormat) {
        byte[] b = new byte[54];
        System.arraycopy(u32(0x00010000L), 0, b, 0, 4);   // version
        System.arraycopy(u32(0x00010000L), 0, b, 4, 4);   // fontRevision
        System.arraycopy(u32(0x5F0F3CF5L), 0, b, 12, 4);  // magicNumber
        System.arraycopy(u16(unitsPerEm), 0, b, 18, 2);   // unitsPerEm
        System.arraycopy(u16(indexToLocFormat), 0, b, 50, 2);
        return b;
    }

    /**
     * 32 字节的 maxp 表：offset 4 为 numGlyphs。
     */
    private static byte[] maxp(int numGlyphs) {
        byte[] b = new byte[32];
        System.arraycopy(u32(0x00010000L), 0, b, 0, 4);
        System.arraycopy(u16(numGlyphs), 0, b, 4, 2);
        return b;
    }

    /**
     * 36 字节的 hhea 表：offset 34 为 numberOfHMetrics。
     */
    private static byte[] hhea(int numberOfHMetrics) {
        byte[] b = new byte[36];
        System.arraycopy(u32(0x00010000L), 0, b, 0, 4);
        System.arraycopy(u16(numberOfHMetrics), 0, b, 34, 2);
        return b;
    }

    /**
     * 含 1 个轮廓、1 个点（坐标 0,0）的简单字形，包围盒为 (0,0)-(100,100)。
     */
    private static byte[] oneContourGlyph() {
        return cat(
                u16(1),                 // numberOfContours
                u16(0), u16(0),         // xMin, yMin
                u16(100), u16(100),     // xMax, yMax
                u16(0),                 // endPtsOfContours[0]
                u16(0),                 // instructionLength
                new byte[]{0},          // flags: x/y 均为 16 位增量
                u16(0), u16(0)          // x, y 增量
        );
    }

    /**
     * cmap 表：单个 format 6 子表（Windows / Unicode BMP）。
     */
    private static byte[] cmapFormat6(int firstCode, int[] glyphIds) {
        ByteArrayOutputStream sub = new ByteArrayOutputStream();
        sub.write(0);
        sub.write(6);                                 // format
        writeU16(sub, 10 + glyphIds.length * 2);      // length
        writeU16(sub, 0);                             // language
        writeU16(sub, firstCode);                     // firstCode
        writeU16(sub, glyphIds.length);               // entryCount
        for (int gid : glyphIds) {
            writeU16(sub, gid);
        }
        byte[] subtable = sub.toByteArray();

        ByteArrayOutputStream out = new ByteArrayOutputStream();
        writeU16(out, 0);   // version
        writeU16(out, 1);   // numTables
        writeU16(out, 3);   // platformId: Windows
        writeU16(out, 1);   // encodingId: Unicode BMP
        writeU32(out, 12);  // subtable offset（相对 cmap 表起始位置）
        out.write(subtable, 0, subtable.length);
        return out.toByteArray();
    }

    /**
     * name 表：Macintosh / Roman / English 的 3 条记录（family、subFamily、PostScript）。
     */
    private static byte[] nameTable(String family, String subFamily, String psName) {
        String[] strings = {family, subFamily, psName};
        int[] nameIds = {1, 2, 6};
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        writeU16(out, 0);
        writeU16(out, strings.length);
        writeU16(out, 6 + 12 * strings.length);   // offsetToStartOfStringStorage
        int stringOffset = 0;
        for (int i = 0; i < strings.length; i++) {
            byte[] value = strings[i].getBytes(StandardCharsets.US_ASCII);
            writeU16(out, 1);                 // platformId: Macintosh
            writeU16(out, 0);                 // encodingId: Roman
            writeU16(out, 0);                 // languageId: English
            writeU16(out, nameIds[i]);
            writeU16(out, value.length);
            writeU16(out, stringOffset);
            stringOffset += value.length;
        }
        for (String value : strings) {
            byte[] bytes = value.getBytes(StandardCharsets.US_ASCII);
            out.write(bytes, 0, bytes.length);
        }
        return out.toByteArray();
    }

    /**
     * 最小可用的 CFF 字体数据（1 个名为 Test 的字体，包含 1 个 endchar 字节的 CharStrings）。
     */
    private static byte[] minimalCff() {
        byte[] header = new byte[]{0x01, 0x00, 0x04, 0x04};
        byte[] nameIndex = cffIndex("Test".getBytes(StandardCharsets.US_ASCII));
        // Top DICT: CharStrings(17) 与 Private(18) 各使用 5 字节整数编码
        ByteArrayOutputStream topDict = new ByteArrayOutputStream();
        byte[] placeholder = cffDictInt(0);
        topDict.write(placeholder, 0, placeholder.length);
        topDict.write(17);                                   // CharStrings
        topDict.write(placeholder, 0, placeholder.length);    // Private size
        topDict.write(placeholder, 0, placeholder.length);    // Private offset
        topDict.write(18);                                   // Private
        byte[] topDictData = topDict.toByteArray();
        byte[] topDictIndex = cffIndex(topDictData);
        byte[] stringIndex = cffIndex();
        byte[] globalSubrIndex = cffIndex();

        byte[] charStrings = cffIndex(new byte[]{0x0e});      // endchar
        int charStringsOffset = header.length + nameIndex.length + topDictIndex.length
                + stringIndex.length + globalSubrIndex.length;
        int privateSize = 0;   // 空的 Private DICT
        int privateOffset = charStringsOffset + charStrings.length;

        ByteArrayOutputStream out = new ByteArrayOutputStream();
        out.write(header, 0, header.length);
        out.write(nameIndex, 0, nameIndex.length);
        out.write(topDictIndex, 0, topDictIndex.length);
        out.write(stringIndex, 0, stringIndex.length);
        out.write(globalSubrIndex, 0, globalSubrIndex.length);
        out.write(charStrings, 0, charStrings.length);
        byte[] data = out.toByteArray();

        // 回填 Top DICT 中的三个偏移量/长度（Top DICT 数据位于 index 数据区起始处）
        int pos = header.length + nameIndex.length + 2 + 1 + 4 * 2;
        writeU32(data, pos + 1, charStringsOffset);
        pos += 6;
        writeU32(data, pos + 1, privateSize);
        pos += 5;
        writeU32(data, pos + 1, privateOffset);
        return data;
    }

    /**
     * 构造 CFF INDEX（每段数据均为非空）。
     */
    private static byte[] cffIndex(byte[]... items) {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        writeU16(out, items.length);
        if (items.length == 0) {
            return out.toByteArray();
        }
        out.write(4);   // offSize
        long offset = 1;
        for (int i = 0; i <= items.length; i++) {
            writeU32(out, offset);
            if (i < items.length) {
                offset += items[i].length;
            }
        }
        for (byte[] item : items) {
            out.write(item, 0, item.length);
        }
        return out.toByteArray();
    }

    private static byte[] cffDictInt(long value) {
        return new byte[]{0x1d, (byte) (value >> 24), (byte) (value >> 16), (byte) (value >> 8), (byte) value};
    }

    private static void writeU16(ByteArrayOutputStream out, int value) {
        out.write((value >> 8) & 0xFF);
        out.write(value & 0xFF);
    }

    private static void writeU32(ByteArrayOutputStream out, long value) {
        out.write((int) ((value >> 24) & 0xFF));
        out.write((int) ((value >> 16) & 0xFF));
        out.write((int) ((value >> 8) & 0xFF));
        out.write((int) (value & 0xFF));
    }

    private static void writeU32(byte[] target, int pos, long value) {
        target[pos] = (byte) (value >> 24);
        target[pos + 1] = (byte) (value >> 16);
        target[pos + 2] = (byte) (value >> 8);
        target[pos + 3] = (byte) value;
    }

    private static byte[] u16(int value) {
        return new byte[]{(byte) ((value >> 8) & 0xFF), (byte) (value & 0xFF)};
    }

    private static byte[] u32(long value) {
        return new byte[]{(byte) ((value >> 24) & 0xFF), (byte) ((value >> 16) & 0xFF),
                (byte) ((value >> 8) & 0xFF), (byte) (value & 0xFF)};
    }

    private static byte[] cat(byte[]... parts) {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        for (byte[] part : parts) {
            out.write(part, 0, part.length);
        }
        return out.toByteArray();
    }
}

