/**
 * Unit tests for {@link PointUtil#calPdfPathPoint(double, double, ST_Box, List, boolean, ST_Array, ST_Box, ST_Array, boolean, double)}.
 * <p>
 * OFD path coordinates are expressed in millimetres (1/72 inch = 0.352777... mm), while PDF user space
 * uses points, therefore every coordinate emitted by the method is expected to be the millimetre value
 * multiplied by 72 / 25.4.
 */
public class PointUtilCalPdfPathPointTests {

    /**
     * PDF points per millimetre: one point is 1/72 inch and one inch is 25.4 mm.
     */
    private static final double PT_PER_MM = 72d / 25.4d;

    private static final double PAGE_WIDTH = 210d;
    private static final double PAGE_HEIGHT = 297d;

    private static void assertMm(String message, double expectedMm, float actual) {
        double expected = expectedMm * PT_PER_MM;
        double delta = Math.max(1e-3d, Math.abs(expected) * 1e-5d);
        assertEquals(expected, (double) actual, delta, message);
    }

    private static PathPoint move(float x, float y) {
        return new PathPoint("M", x, y, 0, 0, 0, 0);
    }

    private static List<PathPoint> listOf(PathPoint... points) {
        return new ArrayList<>(Arrays.asList(points));
    }

    @Test
    @DisplayName("M/L points are converted from millimetres to PDF points without any offset")
    void testMoveAndLinePointsAreExpressedInPdfPoints() {
        List<PathPoint> result = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, null,
                listOf(move(10f, 20f), new PathPoint("L", 30f, 40f, 0, 0, 0, 0)),
                false, null, null, null, false, 1d);

        assertEquals(2, result.size());
        assertEquals("M", result.get(0).type);
        assertMm("M x must be 10 mm in points", 10d, result.get(0).x1);
        assertMm("M y must be 20 mm in points", 20d, result.get(0).y1);
        assertEquals(0f, result.get(0).x2);
        assertEquals(0f, result.get(0).y2);
        assertEquals(0f, result.get(0).x3);
        assertEquals(0f, result.get(0).y3);

        assertEquals("L", result.get(1).type);
        assertMm("L x must be 30 mm in points", 30d, result.get(1).x1);
        assertMm("L y must be 40 mm in points", 40d, result.get(1).y1);
    }

    @Test
    @DisplayName("A value of 72/25.4 maps 25.4 mm to exactly 72 points")
    void testMillimetreToPointFactor() {
        List<PathPoint> result = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, null,
                listOf(move(25.4f, 12.7f)), false, null, null, null, false, 1d);

        assertEquals(72d, (double) result.get(0).x1, 1e-3d,
                "25.4 mm must be 1 inch == 72 points");
        assertEquals(36d, (double) result.get(0).y1, 1e-3d,
                "12.7 mm must be half an inch == 36 points");
    }

    @Test
    @DisplayName("Empty abbreviated point list produces an empty result")
    void testEmptyInputYieldsEmptyList() {
        List<PathPoint> result = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, null,
                new ArrayList<PathPoint>(), false, null, null, null, false, 1d);

        assertTrue(result.isEmpty(), "no input points means no output points");
    }

    @Test
    @DisplayName("fixOriginToPdf flips the Y axis against the page height")
    void testFixOriginToPdfFlipsYAxis() {
        List<PathPoint> result = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, null,
                listOf(move(10f, 20f)), false, null, null, null, true, 1d);

        assertMm("X is not affected by the origin fix", 10d, result.get(0).x1);
        assertMm("Y becomes page height minus the point Y", PAGE_HEIGHT - 20d, result.get(0).y1);
    }

    @Test
    @DisplayName("The boundary top-left corner is added to every coordinate")
    void testBoundaryOffsetIsAdded() {
        ST_Box boundary = new ST_Box(5d, 7d, 100d, 100d);

        List<PathPoint> result = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, boundary,
                listOf(move(10f, 20f)), false, null, null, null, false, 1d);

        assertMm("x = boundary.x + point x", 15d, result.get(0).x1);
        assertMm("y = boundary.y + point y", 27d, result.get(0).y1);
    }

    @Test
    @DisplayName("The boundary offset is part of the coordinate that gets flipped by fixOriginToPdf")
    void testBoundaryOffsetWithFixOriginToPdf() {
        ST_Box boundary = new ST_Box(5d, 7d, 100d, 100d);

        List<PathPoint> result = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, boundary,
                listOf(move(10f, 20f)), false, null, null, null, true, 1d);

        assertMm("x = boundary.x + point x", 15d, result.get(0).x1);
        assertMm("y = page height - (boundary.y + point y)", PAGE_HEIGHT - 27d, result.get(0).y1);
    }

    @Test
    @DisplayName("A non unit scale multiplies the point coordinates")
    void testScaleMultipliesCoordinates() {
        List<PathPoint> result = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, null,
                listOf(move(10f, 20f)), false, null, null, null, false, 2.5d);

        assertMm("x is multiplied by the scale", 25d, result.get(0).x1);
        assertMm("y is multiplied by the scale", 50d, result.get(0).y1);
    }

    @Test
    @DisplayName("A translation CTM is applied to the point before it is converted")
    void testCtmTranslationIsApplied() {
        ST_Array ctm = new ST_Array(1d, 0d, 0d, 1d, 3d, 4d);

        List<PathPoint> result = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, null,
                listOf(move(10f, 20f)), true, ctm, null, null, false, 1d);

        assertMm("x is translated by e", 13d, result.get(0).x1);
        assertMm("y is translated by f", 24d, result.get(0).y1);
    }

    @Test
    @DisplayName("A rotation CTM is applied before the boundary offset")
    void testCtmRotationIsAppliedBeforeBoundary() {
        // rotate 90 degrees: x' = -y, y' = x
        ST_Array ctm = new ST_Array(0d, 1d, -1d, 0d, 0d, 0d);
        ST_Box boundary = new ST_Box(1d, 2d, 100d, 100d);

        List<PathPoint> result = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, boundary,
                listOf(move(10f, 20f)), true, ctm, null, null, false, 1d);

        // (10, 20) -> (-20, 10) -> boundary offset -> (-19, 12)
        assertMm("rotated x plus boundary x", -19d, result.get(0).x1);
        assertMm("rotated y plus boundary y", 12d, result.get(0).y1);
    }

    @Test
    @DisplayName("S and C operators use the first coordinate pair like M and L")
    void testSAndCPointsUseFirstCoordinatePair() {
        List<PathPoint> result = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, null,
                listOf(new PathPoint("S", 11f, 12f, 0, 0, 0, 0),
                        new PathPoint("C", 13f, 14f, 0, 0, 0, 0)),
                false, null, null, null, false, 1d);

        assertEquals(2, result.size());
        assertEquals("S", result.get(0).type);
        assertMm("S x", 11d, result.get(0).x1);
        assertMm("S y", 12d, result.get(0).y1);
        assertEquals("C", result.get(1).type);
        assertMm("C x", 13d, result.get(1).x1);
        assertMm("C y", 14d, result.get(1).y1);
    }

    @Test
    @DisplayName("Bezier control points are all transformed by the CTM")
    void testBezierControlPointsAreTransformed() {
        ST_Array ctm = new ST_Array(1d, 0d, 0d, 1d, 1d, 2d);
        PathPoint bezier = new PathPoint("B", 10f, 20f, 30f, 40f, 50f, 60f);

        List<PathPoint> result = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, null,
                listOf(bezier), true, ctm, null, null, false, 1d);

        assertEquals(1, result.size());
        PathPoint out = result.get(0);
        assertEquals("B", out.type);
        assertMm("control 1 x", 11d, out.x1);
        assertMm("control 1 y", 22d, out.y1);
        assertMm("control 2 x", 31d, out.x2);
        assertMm("control 2 y", 42d, out.y2);
        assertMm("end point x", 51d, out.x3);
        assertMm("end point y", 62d, out.y3);
    }

    @Test
    @DisplayName("Bezier points honour both the scale and the origin fix")
    void testBezierHonoursScaleAndOriginFix() {
        ST_Box boundary = new ST_Box(1d, 1d, 100d, 100d);

        List<PathPoint> result = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, boundary,
                listOf(new PathPoint("B", 10f, 10f, 20f, 20f, 30f, 30f)),
                false, null, null, null, true, 2d);

        PathPoint out = result.get(0);
        // x' = 10*2 + 1 = 21, y' = 10*2 + 1 = 21 -> Y flipped against the page height
        assertMm("first control x", 21d, out.x1);
        assertMm("first control y (flipped)", PAGE_HEIGHT - 21d, out.y1);
        assertMm("second control x", 41d, out.x2);
        assertMm("second control y (flipped)", PAGE_HEIGHT - 41d, out.y2);
        assertMm("end point x", 61d, out.x3);
        assertMm("end point y (flipped)", PAGE_HEIGHT - 61d, out.y3);
    }

    @Test
    @DisplayName("Quadratic curve keeps the third coordinate pair at zero")
    void testQuadraticPointConversion() {
        ST_Array ctm = new ST_Array(1d, 0d, 0d, 1d, 1d, 2d);

        List<PathPoint> result = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, null,
                listOf(new PathPoint("Q", 10f, 20f, 30f, 40f, 0, 0)),
                true, ctm, null, null, false, 1d);

        assertEquals(1, result.size());
        PathPoint out = result.get(0);
        assertEquals("Q", out.type);
        assertMm("control x", 11d, out.x1);
        assertMm("control y", 22d, out.y1);
        assertMm("end x", 31d, out.x2);
        assertMm("end y", 42d, out.y2);
        assertEquals(0f, out.x3, "the third pair of a Q operator stays zero");
        assertEquals(0f, out.y3, "the third pair of a Q operator stays zero");
    }

    @Test
    @DisplayName("Arc operator keeps its radii and flags while transforming the end point")
    void testArcPointConversion() {
        ST_Array ctm = new ST_Array(1d, 0d, 0d, 1d, 2d, 3d);
        PathPoint arc = new PathPoint("A", 5f, 6f, 30f, 1f, 0f, 40f, 50f);

        List<PathPoint> result = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, null,
                listOf(arc), true, ctm, null, null, false, 1d);

        assertEquals(1, result.size());
        PathPoint out = result.get(0);
        assertEquals("A", out.type);
        assertMm("radius x", 5d, out.rx);
        assertMm("radius y", 6d, out.ry);
        assertEquals(30f, out.rotation, "rotation is copied verbatim");
        assertEquals(1f, out.arc, "large arc flag is copied verbatim");
        assertEquals(0f, out.sweep, "sweep flag is copied verbatim");
        assertMm("end point x", 42d, out.x);
        assertMm("end point y", 53d, out.y);
    }

    @Test
    @DisplayName("Arc radii are not multiplied by the page scale but the end point is")
    void testArcRadiiIgnoreScale() {
        List<PathPoint> result = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, null,
                listOf(new PathPoint("A", 5f, 6f, 0f, 0f, 1f, 40f, 50f)),
                false, null, null, null, false, 2d);

        PathPoint out = result.get(0);
        assertMm("radii keep their own value", 5d, out.rx);
        assertMm("radii keep their own value", 6d, out.ry);
        assertMm("end point is scaled", 80d, out.x);
        assertMm("end point is scaled", 100d, out.y);
    }

    @Test
    @DisplayName("Arc end point is flipped when the origin is fixed to the PDF corner")
    void testArcEndPointIsFlipped() {
        List<PathPoint> result = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, null,
                listOf(new PathPoint("A", 5f, 6f, 45f, 1f, 1f, 40f, 50f)),
                false, null, null, null, true, 1d);

        PathPoint out = result.get(0);
        assertMm("end point x", 40d, out.x);
        assertMm("end point y flipped", PAGE_HEIGHT - 50d, out.y);
        assertEquals(45f, out.rotation);
    }

    @Test
    @DisplayName("The composite object boundary offset is applied on top of the adjusted coordinate")
    void testCompositeObjectBoundaryOffset() {
        ST_Box compositeBoundary = new ST_Box(2d, 3d, 50d, 50d);

        List<PathPoint> result = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, null,
                listOf(move(10f, 20f)), false, null, compositeBoundary, null, false, 1d);

        assertMm("x = point x + composite boundary x", 12d, result.get(0).x1);
        assertMm("y = point y + composite boundary y", 23d, result.get(0).y1);
    }

    @Test
    @DisplayName("The composite object boundary offset is included in the origin fix")
    void testCompositeObjectBoundaryWithOriginFix() {
        ST_Box compositeBoundary = new ST_Box(2d, 3d, 50d, 50d);

        List<PathPoint> result = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, null,
                listOf(move(10f, 20f)), false, null, compositeBoundary, null, true, 1d);

        assertMm("x = point x + composite boundary x", 12d, result.get(0).x1);
        assertMm("y is flipped after all offsets", PAGE_HEIGHT - 23d, result.get(0).y1);
    }

    @Test
    @DisplayName("The composite object CTM is applied before the composite object boundary")
    void testCompositeObjectCtmIsApplied() {
        ST_Array compositeCtm = new ST_Array(1d, 0d, 0d, 1d, 5d, 7d);
        ST_Box compositeBoundary = new ST_Box(1d, 1d, 50d, 50d);

        List<PathPoint> result = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, null,
