import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Unit tests for
 * {@link PointUtil#calPdfTextCoordinate(double, double, ST_Box, float, List, boolean, ST_Array, boolean, double)}.
 *
 * <p>The method converts OFD text positioning information into PDF device coordinates.
 * Coordinates are expressed in millimetres and are finally converted to 72 DPI pixels,
 * therefore the expected values below are the millimetre results multiplied by
 * 72/25.4 (2.834645669...).</p>
 */
public class PointUtilCalPdfTextCoordinateTests {

    /**
     * Tolerance used for the millimetre -> 72DPI pixel conversion.
     */
    private static final double EPS = 1e-4;

    /**
     * 72 DPI conversion factor applied by converterDpi.
     */
    private static final double MM_TO_72DPI = 72d / 25.4d;

    private static TextCode code(Double x, Double y, String text) {
        TextCode textCode = new TextCode();
        textCode.setContent(text);
        textCode.setCoordinate(x, y);
        return textCode;
    }

    private static double px(double mm) {
        return mm * MM_TO_72DPI;
    }

    private static void assertPoint(TextCodePoint point, double expectedXmm, double expectedYmm, String expectedText) {
        assertNotNull(point);
        assertEquals(px(expectedXmm), point.getX(), EPS, "unexpected X for glyph '" + expectedText + "'");
        assertEquals(px(expectedYmm), point.getY(), EPS, "unexpected Y for glyph '" + expectedText + "'");
        assertEquals(expectedText, point.getText());
    }

    private static List<String> glyphs(List<TextCodePoint> points) {
        List<String> result = new ArrayList<>(points.size());
        for (TextCodePoint point : points) {
            result.add(point.getText());
        }
        return result;
    }

    private static List<Double> xs(List<TextCodePoint> points) {
        List<Double> result = new ArrayList<>(points.size());
        for (TextCodePoint point : points) {
            result.add(point.getX());
        }
        return result;
    }

    private static List<Double> ys(List<TextCodePoint> points) {
        List<Double> result = new ArrayList<>(points.size());
        for (TextCodePoint point : points) {
            result.add(point.getY());
        }
        return result;
    }

    @Test
    public void onePointPerCharacterAtTheTextCodeOriginWhenNothingElseIsGiven() {
        List<TextCode> textCodes = Collections.singletonList(code(10d, 20d, "ABC"));

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 12f, textCodes, false, null, false, 1.0d);

        assertEquals(3, points.size());
        assertEquals(Arrays.asList("A", "B", "C"), glyphs(points));
        // without DeltaX/DeltaY every glyph of a TextCode stays on the TextCode origin
        for (TextCodePoint point : points) {
            assertPoint(point, 10d, 20d, point.getText());
        }
    }

    @Test
