        List<TextCode> textCodes = Collections.singletonList(code(0d, 0d, raw));

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 12f, textCodes, false, null, false, 1.0d);

        // "&copy;" is dropped and "\n" is removed, the remaining entities become single characters
        assertEquals(Arrays.asList("A", "<", "B", "C", ">", "D", "&", "E", " ", "F", "\"", "G", "'", "H", "I"),
                glyphs(points));
