        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 12f, Collections.singletonList(textCode), false, null, false, 1.0d);

        // 0, +10, +20, +20 (last delta repeated for the trailing glyphs)
        assertEquals(px(0d), points.get(0).getX(), EPS);
        assertEquals(px(10d), points.get(1).getX(), EPS);
