                210d, 100d, boundary, 12f, textCodes, false, null, true, 1.0d);
        List<TextCodePoint> unflipped = PointUtil.calPdfTextCoordinate(
                210d, 100d, boundary, 12f, textCodes, false, null, false, 1.0d);

        // real Y is 2 + 20 = 22, flipped: 100 - 22 = 78
        assertPoint(unflipped.get(0), 11d, 22d, "a");
        assertPoint(flipped.get(0), 11d, 78d, "a");
    }

    @Test
    public void fixOriginToPdfFlipsYForEachGlyphOfADeltaSequence() {
        TextCode textCode = code(0d, 0d, "abc");
        textCode.setDeltaY(new ST_Array("10"));

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 100d, null, 12f, Collections.singletonList(textCode), false, null, true, 1.0d);

        assertEquals(3, points.size());
        assertEquals(px(100d), points.get(0).getY(), EPS);
        assertEquals(px(90d), points.get(1).getY(), EPS);
        assertEquals(px(80d), points.get(2).getY(), EPS);
    }

    @Test
    public void missingCoordinatesAreTreatedAsZero() {
        TextCode textCode = new TextCode();
        textCode.setContent("ab");

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 12f, Collections.singletonList(textCode), false, null, false, 1.0d);

        assertEquals(2, points.size());
        assertPoint(points.get(0), 0d, 0d, "a");
        assertPoint(points.get(1), 0d, 0d, "b");
    }

    @Test
    public void missingCoordinateOnlyDefaultsTheMissingAxis() {
        TextCode textCode = code(null, 30d, "a");

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 12f, Collections.singletonList(textCode), false, null, false, 1.0d);

        assertPoint(points.get(0), 0d, 30d, "a");
    }

    @Test
    public void hasCtmTrueWithNullCtmBehavesLikeNoTransform() {
        List<TextCode> textCodes = Collections.singletonList(code(10d, 20d, "a"));

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 12f, textCodes, true, null, false, 1.0d);

        assertPoint(points.get(0), 10d, 20d, "a");
    }

    @Test
    public void hasCtmFalseIgnoresTheProvidedCtm() {
        List<TextCode> textCodes = Collections.singletonList(code(10d, 20d, "a"));
        ST_Array ctm = new ST_Array(2d, 0d, 0d, 2d, 5d, 5d);

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 12f, textCodes, false, ctm, false, 1.0d);

        assertPoint(points.get(0), 10d, 20d, "a");
    }

    @Test
    public void emptyTextProducesNoPoints() {
        List<TextCode> textCodes = Collections.singletonList(code(10d, 20d, ""));

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 12f, textCodes, false, null, false, 1.0d);

        assertTrue(points.isEmpty());
    }

    @Test
    public void emptyTextCodeListProducesEmptyResult() {
        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 12f, new ArrayList<TextCode>(), false, null, false, 1.0d);

        assertNotNull(points);
        assertTrue(points.isEmpty());
    }

    @Test
    public void mixedTextCodesAreReturnedInOrder() {
        List<TextCode> textCodes = new ArrayList<>();
        textCodes.add(code(1d, 2d, "ab"));
        textCodes.add(code(10d, 20d, ""));
        textCodes.add(code(5d, 7d, "cd"));

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 12f, textCodes, false, null, false, 1.0d);

        assertEquals(Arrays.asList("a", "b", "c", "d"), glyphs(points));
        assertEquals(px(1d), points.get(0).getX(), EPS);
        assertEquals(px(2d), points.get(0).getY(), EPS);
        assertEquals(px(1d), points.get(1).getX(), EPS);
        assertEquals(px(5d), points.get(2).getX(), EPS);
        assertEquals(px(7d), points.get(2).getY(), EPS);
        assertEquals(px(5d), points.get(3).getX(), EPS);
    }

    @Test
    public void fontSizeDoesNotAffectThisOverloadCoordinates() {
        List<TextCodePoint> small = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 1f, Collections.singletonList(code(10d, 20d, "ab")), false, null, false, 1.0d);
        List<TextCodePoint> large = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 96f, Collections.singletonList(code(10d, 20d, "ab")), false, null, false, 1.0d);

        assertEquals(xs(small), xs(large));
        assertEquals(ys(small), ys(large));
    }

    @Test
    public void glyphListKeepsOneEntryPerCharacterForLongText() {
        StringBuilder builder = new StringBuilder();
        for (int i = 0; i < 50; i++) {
            builder.append((char) ('a' + (i % 26)));
        }
        String text = builder.toString();

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 12f, Collections.singletonList(code(0d, 0d, text)), false, null, false, 1.0d);

        assertEquals(50, points.size());
        assertEquals(text.substring(0, 1), points.get(0).getText());
        assertEquals(text.substring(49, 50), points.get(49).getText());
    }

    @Test
    public void textCodeWithoutContentContributesNoGlyphs() {
        TextCode withoutContent = new TextCode();
        withoutContent.setCoordinate(1d, 2d);
        TextCode withContent = code(3d, 4d, "z");

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 12f, Arrays.asList(withoutContent, withContent), false, null, false, 1.0d);

        assertEquals(1, points.size());
        assertPoint(points.get(0), 3d, 4d, "z");
    }

    @Test
    public void textCodesListContainingOnlyEmptyTextYieldsNoPoints() {
        TextCode empty = new TextCode();
        empty.setCoordinate(1d, 2d);

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 12f, Collections.singletonList(empty), false, null, false, 1.0d);

        assertTrue(points.isEmpty());
    }
}

