package org.ofdrw.converter.utils;

import org.junit.jupiter.api.Test;
import org.ofdrw.converter.point.TextCodePoint;
import org.ofdrw.core.basicType.ST_Array;
import org.ofdrw.core.basicType.ST_Box;
import org.ofdrw.core.text.CT_CGTransform;
import org.ofdrw.core.text.TextCode;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Tests for {@link PointUtil#calPdfTextCoordinate(double, double, ST_Box, float, List, List, ST_Box, ST_Array, boolean, ST_Array, boolean, double)}
 * <p>
 * All expected coordinates are expressed in millimetres of the object coordinate system and converted with
 * {@link CommonUtil#converterDpi(double)} the same way the production code converts them to device pixels.
 */
public class PointUtilCalPdfTextCoordinateTests {

    private static final double EPS = 1e-9;

    /* ------------------------------------------------------------------
     * helpers
     * ------------------------------------------------------------------ */

    private static double px(double mm) {
        return CommonUtil.converterDpi(mm);
    }

    private static TextCode code(String text, Double x, Double y) {
        TextCode textCode = new TextCode();
        textCode.setContent(text);
        textCode.setX(x);
        textCode.setY(y);
        return textCode;
    }

    private static void assertPosition(TextCodePoint point, double expectedXmm, double expectedYmm) {
        assertNotNull(point);
        assertEquals(px(expectedXmm), point.getX(), EPS, "unexpected X coordinate");
        assertEquals(px(expectedYmm), point.getY(), EPS, "unexpected Y coordinate");
    }

    private static List<String> texts(List<TextCodePoint> points) {
        List<String> res = new ArrayList<>(points.size());
        for (TextCodePoint point : points) {
            res.add(point.getText());
        }
        return res;
    }

    private static List<TextCodePoint> call(double width, double height, ST_Box boundary, float fontSize,
                                            List<TextCode> textCodes, List<CT_CGTransform> cgTransforms,
                                            ST_Box compositeObjectBoundary, ST_Array compositeObjectCTM,
                                            boolean hasCtm, ST_Array ctm,
                                            boolean fixOriginToPdf, double scale) {
        return PointUtil.calPdfTextCoordinate(width, height, boundary, fontSize, textCodes, cgTransforms,
                compositeObjectBoundary, compositeObjectCTM, hasCtm, ctm, fixOriginToPdf, scale);
    }

    /**
     * Plain (no CTM, no delta, no boundary, scale 1) invocation, everything else at its neutral value.
     */
    private static List<TextCodePoint> plain(List<TextCode> textCodes) {
        return call(0, 0, null, 10f, textCodes, Collections.<CT_CGTransform>emptyList(), null, null,
                false, null, false, 1.0);
    }

    /* ------------------------------------------------------------------
     * normal cases
     * ------------------------------------------------------------------ */

    @Test
    public void singleTextCodeIsSplitPerCharacterAtItsOrigin() {
        List<TextCodePoint> points = plain(Collections.singletonList(code("AB", 1d, 2d)));

        assertEquals(2, points.size());
        assertPosition(points.get(0), 1, 2);
        assertPosition(points.get(1), 1, 2);
        assertEquals(Arrays.asList("A", "B"), texts(points));
    }

    @Test
    public void emptyTextProducesNoPoints() {
        List<TextCodePoint> points = plain(Collections.singletonList(code("", 5d, 6d)));

        assertTrue(points.isEmpty(), "an empty text must not produce any TextCodePoint");
    }

    @Test
    public void emptyTextCodeListProducesEmptyResultEvenWithCgTransforms() {
        CT_CGTransform transform = new CT_CGTransform()
                .setCodePosition(0)
                .setCodeCount(1)
                .setGlyphCount(1)
                .setGlyphs(new ST_Array("g0"));

        List<TextCodePoint> points = call(100, 100, null, 10f, Collections.<TextCode>emptyList(),
                Collections.singletonList(transform), null, null, false, null, false, 1.0);

        assertTrue(points.isEmpty());
    }

    @Test
    public void coordinatesMissingOnTextCodeDefaultToZero() {
        List<TextCode> textCodes = Arrays.asList(code("A", 1d, 2d), code("B", null, null));

        List<TextCodePoint> points = plain(textCodes);

        assertEquals(2, points.size());
        assertPosition(points.get(0), 1, 2);
        assertPosition(points.get(1), 0, 0);
        assertEquals(Arrays.asList("A", "B"), texts(points));
    }

    @Test
    public void eachTextCodeStartsFromItsOwnOriginWithoutInheritingPreviousPosition() {
        TextCode first = code("AB", 1d, 1d);
        first.setDeltaX(2d);
        TextCode second = code("C", 5d, 5d);

        List<TextCodePoint> points = plain(Arrays.asList(first, second));

        assertEquals(3, points.size());
        assertPosition(points.get(0), 1, 1);
        assertPosition(points.get(1), 3, 1);
        assertPosition(points.get(2), 5, 5);
        assertEquals(Arrays.asList("A", "B", "C"), texts(points));
    }

    @Test
    public void htmlEntitiesAreDecodedAndLineBreaksRemoved() {
        List<TextCodePoint> points = plain(Collections.singletonList(
                code("&lt;&gt;&amp;&nbsp;&quot;&copy;&apos;\nX", 0d, 0d)));

        assertEquals(Arrays.asList("<", ">", "&", " ", "\"", "'", "X"), texts(points));
        assertEquals(7, points.size());
    }

    @Test
    public void replacementsAreAppliedOnlyOnce() {
        // "&amp;lt;" must not become "<": the &lt; replacement happens before the &amp; replacement.
        List<TextCodePoint> points = plain(Collections.singletonList(code("&amp;lt;", 0d, 0d)));

        assertEquals(Arrays.asList("&", "l", "t", ";"), texts(points));
    }

    /* ------------------------------------------------------------------
     * delta handling
     * ------------------------------------------------------------------ */

    @Test
    public void deltaXIsAccumulatedPerCharacter() {
        TextCode textCode = code("ABC", 0d, 0d);
        textCode.setDeltaX(2d, 3d);

        List<TextCodePoint> points = plain(Collections.singletonList(textCode));

        assertEquals(3, points.size());
        assertPosition(points.get(0), 0, 0);
        assertPosition(points.get(1), 2, 0);
        assertPosition(points.get(2), 5, 0);
    }

    @Test
    public void deltaYIsAccumulatedPerCharacter() {
        TextCode textCode = code("ABC", 0d, 10d);
        textCode.setDeltaY(1.5d, -0.5d);

        List<TextCodePoint> points = plain(Collections.singletonList(textCode));

        assertEquals(3, points.size());
        assertPosition(points.get(0), 0, 10);
        assertPosition(points.get(1), 0, 11.5);
        assertPosition(points.get(2), 0, 11);
    }

    @Test
    public void deltaIndexIsClampedToTheLastElement() {
        TextCode textCode = code("ABC", 0d, 0d);
        textCode.setDeltaX(4d);

        List<TextCodePoint> points = plain(Collections.singletonList(textCode));

        assertEquals(3, points.size());
        assertPosition(points.get(0), 0, 0);
        assertPosition(points.get(1), 4, 0);
        assertPosition(points.get(2), 8, 0);
    }

    @Test
    public void zeroDeltaKeepsEveryCharacterAtTheOrigin() {
        TextCode textCode = code("AB", 3d, 4d);
        textCode.setDeltaX(0d, 0d);
        textCode.setDeltaY(0d, 0d);

        List<TextCodePoint> points = plain(Collections.singletonList(textCode));

        assertEquals(2, points.size());
        assertPosition(points.get(0), 3, 4);
        assertPosition(points.get(1), 3, 4);
    }

    @Test
    public void nonNumericDeltaIsRejected() {
        TextCode textCode = code("AB", 0d, 0d);
        textCode.setDeltaX(new ST_Array("abc"));

        assertThrows(NumberFormatException.class,
                () -> plain(Collections.singletonList(textCode)));
    }

    /* ------------------------------------------------------------------
     * boundary, scale and y-flip
     * ------------------------------------------------------------------ */

    @Test
    public void nullBoundaryAndNeutralScaleKeepScaledCoordinatesAndIgnorePageSize() {
        List<TextCodePoint> points = call(1000, 500, null, 10f,
                Collections.singletonList(code("A", 1d, 2d)),
                Collections.<CT_CGTransform>emptyList(), null, null, false, null, false, 1.0);

        assertEquals(1, points.size());
        assertPosition(points.get(0), 1, 2);
    }

    @Test
    public void scaleIsAppliedBeforeBoundaryTranslation() {
        ST_Box boundary = new ST_Box(10d, 20d, 100d, 50d);

        List<TextCodePoint> points = call(1000, 500, boundary, 10f,
                Collections.singletonList(code("A", 1d, 2d)),
                Collections.<CT_CGTransform>emptyList(), null, null, false, null, false, 2.0);

        assertEquals(1, points.size());
        // 10 + 1 * 2 = 12 ; 20 + 2 * 2 = 24
        assertPosition(points.get(0), 12, 24);
    }

    @Test
    public void boundaryTranslationIsAppliedWithNeutralScale() {
        ST_Box boundary = new ST_Box(-5d, 3.5d, 100d, 50d);

        List<TextCodePoint> points = call(1000, 500, boundary, 10f,
                Collections.singletonList(code("A", 1d, 2d)),
                Collections.<CT_CGTransform>emptyList(), null, null, false, null, false, 1.0);

        assertEquals(1, points.size());
        assertPosition(points.get(0), -4, 5.5);
    }

    @Test
    public void fixOriginToPdfFlipsYAgainstHeight() {
        List<TextCodePoint> points = call(200, 100, null, 10f,
                Collections.singletonList(code("A", 1d, 20d)),
                Collections.<CT_CGTransform>emptyList(), null, null, false, null, true, 1.0);

        assertEquals(1, points.size());
        assertPosition(points.get(0), 1, 80);
    }

    @Test
    public void fixOriginToPdfFlipsAfterBoundaryAndScale() {
        ST_Box boundary = new ST_Box(0d, 10d, 100d, 50d);

        List<TextCodePoint> points = call(200, 100, boundary, 10f,
                Collections.singletonList(code("A", 1d, 20d)),
                Collections.<CT_CGTransform>emptyList(), null, null, false, null, true, 2.0);

        // y = 10 + 20 * 2 = 50 -> 100 - 50 = 50
        assertEquals(1, points.size());
        assertPosition(points.get(0), 2, 50);
    }

    /* ------------------------------------------------------------------
     * CTM handling
     * ------------------------------------------------------------------ */

    @Test
    public void ctmTransformsTheTextOriginIncludingTranslation() {
        ST_Array ctm = new ST_Array(2d, 0d, 0d, 2d, 10d, 20d);

        List<TextCodePoint> points = call(0, 0, null, 10f,
                Collections.singletonList(code("AB", 1d, 2d)),
                Collections.<CT_CGTransform>emptyList(), null, null, true, ctm, false, 1.0);

        assertEquals(2, points.size());
        // x = 1 * 2 + 2 * 0 + 10 = 12 ; y = 1 * 0 + 2 * 2 + 20 = 24
        assertPosition(points.get(0), 12, 24);
        assertPosition(points.get(1), 12, 24);
    }

    @Test
    public void missingCtmWhileHasCtmIsTrueFails() {
        assertThrows(NullPointerException.class, () -> call(0, 0, null, 10f,
                Collections.singletonList(code("A", 1d, 2d)),
                Collections.<CT_CGTransform>emptyList(), null, null, true, null, false, 1.0));
    }

    @Test
    public void deltaXIsTransformedByTheLinearPartOfTheCtm() {
        ST_Array ctm = new ST_Array(2d, 0d, 0d, 2d, 10d, 20d);
        TextCode textCode = code("AB", 0d, 0d);
        textCode.setDeltaX(3d);

        List<TextCodePoint> points = call(0, 0, null, 10f,
                Collections.singletonList(textCode),
                Collections.<CT_CGTransform>emptyList(), null, null, true, ctm, false, 1.0);

        assertEquals(2, points.size());
        // origin (10, 20); dx 3 is scaled by a = 2 -> 6 -> x = 16
        assertPosition(points.get(0), 10, 20);
        assertPosition(points.get(1), 16, 20);
    }

    @Test
    public void deltaXBecomesVerticalStepForRotatedVerticalText() {
        // a == 0 && d == 0: dx is mapped onto the vertical component and returned as absolute value
        ST_Array ctm = new ST_Array(0d, -2d, 1d, 0d, 5d, 7d);
        TextCode textCode = code("AB", 0d, 0d);
        textCode.setDeltaX(3d);

        List<TextCodePoint> points = call(0, 0, null, 10f,
                Collections.singletonList(textCode),
