        textCode.setDeltaY(2d);

        List<TextCodePoint> points = call(0, 0, null, 10f,
                Collections.singletonList(textCode),
                Collections.<CT_CGTransform>emptyList(), null, null, true, ctm, false, 1.0);

        assertEquals(2, points.size());
        // origin (10, 20); dy 2 is scaled by d = 3 -> 6 -> y = 26
        assertPosition(points.get(0), 10, 20);
        assertPosition(points.get(1), 10, 26);
    }

    @Test
    public void deltaYIsMultipliedByFontSizeForRotatedVerticalText() {
        ST_Array ctm = new ST_Array(0d, -2d, 1d, 0d, 0d, 0d);
        TextCode textCode = code("AB", 0d, 0d);
        textCode.setDeltaY(2d);

        List<TextCodePoint> points = call(0, 0, null, 4f,
                Collections.singletonList(textCode),
                Collections.<CT_CGTransform>emptyList(), null, null, true, ctm, false, 1.0);

