                Collections.singletonList(code("A", 1d, 2d)),
                Collections.<CT_CGTransform>emptyList(), null, compositeCtm, false, null, false, 1.0);

        assertEquals(1, points.size());
        assertPosition(points.get(0), 6, 8);
    }

