        assertEquals(1, points.size());
        // the 12 argument overload positions text with the object boundary only
        assertPosition(points.get(0), 1, 2);
    }

    @Test
    public void allTransformationsAreCombined() {
        ST_Array ctm = new ST_Array(2d, 0d, 0d, 2d, 1d, 1d);
        ST_Array compositeCtm = new ST_Array(1d, 0d, 0d, 1d, 1d, 1d);
        ST_Box boundary = new ST_Box(5d, 5d, 0d, 0d);

        List<TextCodePoint> points = call(200, 100, boundary, 10f,
                Collections.singletonList(code("A", 1d, 1d)),
                Collections.<CT_CGTransform>emptyList(), null, compositeCtm, true, ctm, true, 2.0);

        assertEquals(1, points.size());
        // ctm -> (3, 3); *2 + boundary -> (11, 11); + (1, 1) -> (12, 12); flip -> 100 - 12 = 88
        assertPosition(points.get(0), 12, 88);
    }

    /* ------------------------------------------------------------------
     * CGTransform / glyph handling
     * ------------------------------------------------------------------ */

    @Test
    public void glyphsAreAssignedToTheCorrespondingCodePoints() {
        CT_CGTransform transform = new CT_CGTransform()
                .setCodePosition(0)
                .setCodeCount(2)
                .setGlyphCount(2)
                .setGlyphs(new ST_Array("g0", "g1"));

