                Collections.singletonList(code("AB", 0d, 0d)),
                Collections.singletonList(transform), null, null, false, null, false, 1.0);

        assertEquals(2, points.size());
        assertEquals("g0", points.get(0).getGlyph());
        assertEquals("g1", points.get(1).getGlyph());
    }

    @Test
    public void extraGlyphsAreAppendedToTheLastCodePoint() {
        CT_CGTransform transform = new CT_CGTransform()
                .setCodePosition(0)
                .setCodeCount(3)
                .setGlyphCount(3)
                .setGlyphs(new ST_Array("g0", "g1", "g2"));

