        assertEquals(2, points.size());
        assertEquals("g0", points.get(0).getGlyph());
        assertEquals("g1 g2", points.get(1).getGlyph());
    }

    @Test
    public void glyphsAreNullWhenNoCgTransformIsGiven() {
        List<TextCodePoint> points = plain(Collections.singletonList(code("AB", 0d, 0d)));

        assertEquals(2, points.size());
        assertNull(points.get(0).getGlyph());
        assertNull(points.get(1).getGlyph());
    }

    @Test
    public void positionIsDroppedWhenTransformHasFewerGlyphsThanCodes() {
        CT_CGTransform transform = new CT_CGTransform()
                .setCodePosition(0)
                .setCodeCount(2)
                .setGlyphCount(1)
                .setGlyphs(new ST_Array("g0"));
        TextCode textCode = code("AB", 0d, 0d);
        textCode.setDeltaX(5d);

        List<TextCodePoint> points = call(0, 0, null, 10f,
                Collections.singletonList(textCode),
                Collections.singletonList(transform), null, null, false, null, false, 1.0);

        assertEquals(2, points.size());
        // the blanked character must not consume the delta
        assertEquals(Arrays.asList("A", ""), texts(points));
        assertPosition(points.get(0), 0, 0);
        assertPosition(points.get(1), 0, 0);
        assertEquals("g0", points.get(0).getGlyph());
    }

    @Test
    public void positionIsKeptWhenTransformCoversEveryCodeWithEnoughGlyphs() {
        CT_CGTransform transform = new CT_CGTransform()
                .setCodePosition(0)
                .setCodeCount(2)
                .setGlyphCount(2)
                .setGlyphs(new ST_Array("g0", "g1"));
        TextCode textCode = code("AB", 0d, 0d);
        textCode.setDeltaX(5d);

        List<TextCodePoint> points = call(0, 0, null, 10f,
                Collections.singletonList(textCode),
                Collections.singletonList(transform), null, null, false, null, false, 1.0);

        assertEquals(2, points.size());
        assertEquals(Arrays.asList("A", "B"), texts(points));
        assertPosition(points.get(0), 0, 0);
        assertPosition(points.get(1), 5, 0);
    }
}

