                buildSignedData(new ContentInfo(OIDs.data, new DEROctetString(tbsDigest)),
                        signerInfoWithoutAttributes(signature),
                        new DERSet(asn1Cert)));

        VerifyInfo info = GBT35275Validate.validate(SM2_SIGN_ALG, tbsContent, signedValue);

        assertFalse(info.result, "签名与待验数据不对应时不应通过验证");
        assertEquals("签名值不一致", info.hit);
    }

    // ------------------------------------------------------------------
    // 证书缺失
    // ------------------------------------------------------------------

    @Test
    @DisplayName("签名值中不存在与签名者匹配的证书时返回未找到证书")
    void validateReturnsErrWhenCertificateIsMissing() throws Exception {
        byte[] signature = sign(tbsDigest);
        byte[] signedValue = toSignedValue(
                buildSignedData(new ContentInfo(OIDs.data, new DEROctetString(tbsDigest)),
                        signerInfoWithoutAttributes(signature),
                        new DERSet()));

        VerifyInfo info = GBT35275Validate.validate(SM2_SIGN_ALG, tbsContent, signedValue);

        assertFalse(info.result, "没有证书时应验证失败");
        assertEquals("没有找到匹配的证书无法验证签名", info.hit);
    }

    // ------------------------------------------------------------------
    // 非法输入与异常场景
    // ------------------------------------------------------------------

    @Test
    @DisplayName("内容类型不是signedData时抛出IllegalArgumentException")
    void validateThrowsWhenContentTypeIsNotSignedData() throws Exception {
        ContentInfo notSignedData = new ContentInfo(OIDs.data, new DEROctetString(tbsDigest));
        byte[] signedValue = notSignedData.toASN1Primitive().getEncoded("DER");

        IllegalArgumentException ex = assertThrows(IllegalArgumentException.class,
                () -> GBT35275Validate.validate(SM2_SIGN_ALG, tbsContent, signedValue));
        assertTrue(ex.getMessage().startsWith("非法的签名数据类型"),
                "异常信息应说明签名数据类型非法，实际为：" + ex.getMessage());
        assertTrue(ex.getMessage().contains(OIDs.data.getId()),
                "异常信息应包含实际的内容类型 OID");
    }

    @Test
    @DisplayName("SignedData内容无法解析时抛出IllegalArgumentException")
    void validateThrowsWhenContentCannotBeParsedAsSignedData() throws Exception {
        // signedData 类型，但内容是一个普通 OCTET STRING，无法解析为 SignedData 结构
        ContentInfo broken = new ContentInfo(OIDs.signedData, new DEROctetString(tbsDigest));
        byte[] signedValue = broken.toASN1Primitive().getEncoded("DER");

        assertThrows(IllegalArgumentException.class,
                () -> GBT35275Validate.validate(SM2_SIGN_ALG, tbsContent, signedValue));
    }

    @Test
    @DisplayName("签名值为null时抛出无法解析ContentInfo结构")
    void validateThrowsWhenSignedValueIsNull() {
        IllegalArgumentException ex = assertThrows(IllegalArgumentException.class,
                () -> GBT35275Validate.validate(SM2_SIGN_ALG, tbsContent, null));
        assertEquals("无法解析ContentInfo结构", ex.getMessage());
    }

    @Test
    @DisplayName("签名值字节流无法解析时抛出异常")
    void validateThrowsWhenSignedValueIsNotASN1Sequence() {
        byte[] garbage = new byte[]{0x01, 0x02, 0x03};
        assertThrows(RuntimeException.class,
                () -> GBT35275Validate.validate(SM2_SIGN_ALG, tbsContent, garbage));
    }

    @Test
    @DisplayName("内容不是OCTET STRING时抛出IllegalArgumentException")
    void validateThrowsWhenContentIsNotOctetString() throws Exception {
        ContentInfo contentInfo = new ContentInfo(OIDs.data, new ASN1Integer(64));
        byte[] signedValue = toSignedValue(buildSignedData(contentInfo,
                signerInfoWithoutAttributes(sign(tbsDigest)),
                new DERSet(asn1Cert)));

        assertThrows(IllegalArgumentException.class,
                () -> GBT35275Validate.validate(SM2_SIGN_ALG, tbsContent, signedValue));
    }

    @Test
    @DisplayName("既无内容也无认证属性时抛出GBT35275签名值格式错误")
    void validateThrowsWhenPlaintextIsAbsent() throws Exception {
        byte[] signedValue = toSignedValue(
                buildSignedData(new ContentInfo(OIDs.data, null),
                        signerInfoWithoutAttributes(sign(tbsDigest)),
                        new DERSet(asn1Cert)));

        IllegalArgumentException ex = assertThrows(IllegalArgumentException.class,
                () -> GBT35275Validate.validate(SM2_SIGN_ALG, tbsContent, signedValue));
        assertEquals("GBT35275签名值格式错误", ex.getMessage());
    }

    @Test
    @DisplayName("PKCS#9 message-digest属性不是OCTET STRING时抛出IllegalArgumentException")
    void validateThrowsWhenPkcs9MessageDigestIsNotOctetString() throws Exception {
        Attribute badDigest = new Attribute(CMSAttributes.messageDigest, new DERSet(new ASN1Integer(1024)));
        ASN1Set authenticatedAttributes = new DERSet(badDigest);
        byte[] signature = sign(authenticatedAttributes.getEncoded("DER"));
        byte[] signedValue = toSignedValue(
                buildSignedData(new ContentInfo(OIDs.data, new DEROctetString(tbsDigest)),
                        signerInfoWithAttributes(signature, authenticatedAttributes),
                        new DERSet(asn1Cert)));

        IllegalArgumentException ex = assertThrows(IllegalArgumentException.class,
                () -> GBT35275Validate.validate(SM2_SIGN_ALG, tbsContent, signedValue));
        assertTrue(ex.getMessage().contains("OCTET STRING"),
                "异常信息应说明属性类型不是 OCTET STRING，实际为：" + ex.getMessage());
    }

    @Test
    @DisplayName("签名算法名称不可用时抛出NoSuchAlgorithmException")
    void validateThrowsWhenAlgorithmIsUnknown() throws Exception {
        byte[] signature = sign(tbsDigest);
        byte[] signedValue = toSignedValue(
                buildSignedData(new ContentInfo(OIDs.data, new DEROctetString(tbsDigest)),
                        signerInfoWithoutAttributes(signature),
                        new DERSet(asn1Cert)));

        assertThrows(NoSuchAlgorithmException.class,
                () -> GBT35275Validate.validate("NOT-A-SM2-ALGORITHM", tbsContent, signedValue));
    }

    // ------------------------------------------------------------------
    // 辅助方法
    // ------------------------------------------------------------------

    /**
     * 使用测试私钥对待签名数据做 SM2 签名
     *
     * @param data 待签名数据
     * @return 签名值
     */
    private static byte[] sign(byte[] data) throws Exception {
        Signature sg = Signature.getInstance(SM2_SIGN_ALG, BC);
        sg.initSign(keyPair.getPrivate());
        sg.update(data);
        return sg.sign();
    }

    /**
     * 构造不带认证属性的签名者信息
     */
    private static SignerInfo signerInfoWithoutAttributes(byte[] signature) {
        return newSignerInfo(signature, null);
    }

    /**
     * 构造带认证属性的签名者信息
     */
    private static SignerInfo signerInfoWithAttributes(byte[] signature, ASN1Set authenticatedAttributes) {
        return newSignerInfo(signature, authenticatedAttributes);
    }

    private static SignerInfo newSignerInfo(byte[] signature, ASN1Set authenticatedAttributes) {
        IssuerAndSerialNumber iaSn =
                new IssuerAndSerialNumber(asn1Cert.getIssuer(), asn1Cert.getSerialNumber());
        SignerInfo signerInfo = new SignerInfo(
                iaSn,
                new AlgorithmIdentifier(OIDs.sm3),
                new AlgorithmIdentifier(OIDs.sm2Sign),
                new DEROctetString(signature));
        signerInfo.setAuthenticatedAttributes(authenticatedAttributes);
        return signerInfo;
    }

    /**
     * 构造只包含 PKCS#9 message-digest 属性的认证属性集合
     */
    private static ASN1Set authenticatedAttributes(byte[] messageDigest) {
        Attribute messageDigestAttr = new Attribute(
                CMSAttributes.messageDigest,
                new DERSet(new DEROctetString(messageDigest)));
        Attribute contentTypeAttr = new Attribute(CMSAttributes.contentType, new DERSet(OIDs.data));
        return new DERSet(new ASN1Encodable[]{contentTypeAttr, messageDigestAttr});
    }

    private static SignedData buildSignedData(ContentInfo contentInfo, SignerInfo signerInfo, ASN1Set certificates) {
        return buildSignedData(contentInfo, new DERSet(signerInfo), certificates);
    }

    private static SignedData buildSignedData(ContentInfo contentInfo, ASN1Set signerInfos, ASN1Set certificates) {
        return new SignedData(
                new DERSet(new AlgorithmIdentifier(OIDs.sm3)),
                contentInfo,
                certificates,
                signerInfos);
    }

    /**
     * 将 SignedData 包装为 OIDs.signedData 类型的 ContentInfo 并编码为 DER
     */
    private static byte[] toSignedValue(SignedData signedData) throws Exception {
        ContentInfo contentInfo = new ContentInfo(OIDs.signedData, signedData);
        return contentInfo.toASN1Primitive().getEncoded("DER");
    }
}

