        assertEquals(105L, vectorId.getId().longValue());
        assertEquals(105, maxUnitID.get());

        Set<Long> ids = new HashSet<>();
        ids.add(colorId.getId());
        ids.add(fontId.getId());
        ids.add(drawParamId.getId());
        ids.add(mediaId.getId());
        ids.add(vectorId.getId());
        assertEquals(5, ids.size());

        Res publicRes = publicResources();
        assertEquals(2, publicRes.getResources().size());
        assertEquals(1, publicRes.getFonts().size());
        boolean hasColorSpaces = false;
        for (OFDResource resource : publicRes.getResources()) {
            if (resource instanceof ColorSpaces) {
                hasColorSpaces = true;
                assertEquals(1, ((ColorSpaces) resource).getColorSpaces().size());
            }
        }
        assertTrue(hasColorSpaces);

        Res documentRes = documentResources();
        assertEquals(3, documentRes.getResources().size());
        boolean hasDrawParams = false;
        boolean hasMultiMedias = false;
        boolean hasCompositeGraphicUnits = false;
        for (OFDResource resource : documentRes.getResources()) {
            hasDrawParams |= resource instanceof DrawParams;
            hasMultiMedias |= resource instanceof MultiMedias;
            hasCompositeGraphicUnits |= resource instanceof CompositeGraphicUnits;
        }
        assertTrue(hasDrawParams);
        assertTrue(hasMultiMedias);
        assertTrue(hasCompositeGraphicUnits);
        assertFalse(publicRes.getResources().isEmpty());

        CT_CommonData commonData = docDir.getDocument().getCommonData();
        assertEquals(1, commonData.getPublicResList().size());
        assertEquals(1, commonData.getDocumentResList().size());
    }
