        Rectangle rect = p.doPrepare(100.0);

        assertNotNull(rect);
        assertEquals(18.0, rect.getWidth(), EPS, "返回矩形的宽度为最长行宽度");
        assertEquals(lineHeight() + HEIGHT_FIX, rect.getHeight(), EPS, "返回矩形的高度为所有行高度之和加精度补偿");
        assertEquals(18.0, p.getWidth(), EPS, "未设置宽度的段落在完成后宽度为最长行宽度");
        assertEquals(lineHeight() + HEIGHT_FIX, p.getHeight(), EPS);
        assertEquals(1, p.getLines().size(), "文字应全部加入同一行");
        assertEquals(18.0, p.getLines().get(0).getWidth(), EPS);
        assertEquals(100.0, p.getLines().get(0).getLineMaxAvailableWidth(), EPS);
