            }
        }
        if (outPath != null) {
            Files.deleteIfExists(outPath);
        }
    }

    @Test
    void ignoresNullEmptyAndWhitespaceOnlyTextWithoutAllocatingAnything() throws IOException {
        int initialId = maxUnitID.get();

        assertSame(context, context.fillText(null, 1, 2));
        assertSame(context, context.fillText("", 3, 4));
        assertSame(context, context.fillText(" \t\r\n ", 5, 6));

