        assertTrue(textObject.getItalic());
        assertEquals(Direction.Angle_180, textObject.getReadDirection());
        assertEquals(Direction.Angle_90, textObject.getCharDirection());

        TextCode textCode = textObject.getTextCodes().get(0);
        // For read=180,char=90 the first glyph is shifted by (-size,-size).
        // The inter-glyph offset is -(2.5 + 0.5) = -3, and width is 3 + 2.5 = 5.5.
        // Right alignment in the reversed reading direction adds the width back.
        assertEquals(103.0, textCode.getX(), 1e-4);
        assertEquals(47.5, textCode.getY(), 1e-4);
        assertNull(textCode.getDeltaY());
        assertNotNull(textCode.getDeltaX());
        assertArrayEquals(new Double[]{-3.0}, textCode.getDeltaX().toDouble());
    }

    @Test
    void usesDeltaYAndFontSizeOffsetForVerticalReadingDirection() throws IOException {
        FontSetting font = new FontSetting(2, FontName.SimSun.font())
                .setReadDirection(90)
                .setCharDirection(0)
                .setTextAlign(TextAlign.start);
        context.setFont(font);

        context.fillText("XYZ", 7, 9);

        TextObject textObject = firstTextObject();
        assertEquals(Direction.Angle_90, textObject.getReadDirection());
        assertEquals(Direction.Angle_0, textObject.getCharDirection());

        TextCode textCode = textObject.getTextCodes().get(0);
        assertEquals("XYZ", textCode.getContent());
