        assertEquals(7.0, textCode.getX(), EPS);
        assertEquals(11.0, textCode.getY(), EPS);
        assertNull(textCode.getDeltaX());
        assertNotNull(textCode.getDeltaY());
        assertArrayEquals(new Double[]{2.0, 2.0}, textCode.getDeltaY().toDouble());
