        assertEquals(100 - measuredWidth / 2, textCode.getX(), EPS);
        assertEquals(20, textCode.getY(), EPS);
    }

    @Test
    void rightAlignmentShiftsHorizontalTextByFullMeasuredWidth() throws IOException {
        double measuredWidth = context.measureText("ABC").width;
        context.setTextAlign(TextAlign.right);

        context.fillText("ABC", 100, 20);

        TextCode textCode = firstTextObject().getTextCodes().get(0);
        assertEquals(100 - measuredWidth, textCode.getX(), EPS);
        assertEquals(20, textCode.getY(), EPS);
    }

    @Test
    void parsesFontStyleAndRegistersFontResource() throws IOException {
        context.font = "italic 800 12px SimSun";

        context.fillText("Q", 10, 20);

        TextObject textObject = firstTextObject();
        assertEquals(12.0 / context.PPM, textObject.getSize(), EPS);
        assertEquals(Weight.W_800, textObject.getWeight());
        assertTrue(textObject.getItalic());
        assertNotNull(doc.getResManager().getFont("SimSun"));
    }

    @Test
    void reusesExistingFontAndAssignsSequentialObjectIds() throws IOException {
        context.font = "12mm SimSun";

        context.fillText("A", 10, 20);
        context.fillText("B", 30, 40);

        List<PageBlockType> blocks = container.getPageBlocks();
        assertEquals(2, blocks.size());
        TextObject first = (TextObject) blocks.get(0);
        TextObject second = (TextObject) blocks.get(1);
        assertEquals(101L, first.getID().getId().longValue());
        assertEquals(102L, second.getID().getId().longValue());
        assertEquals(first.getFont().getRefId(), second.getFont().getRefId());
        assertEquals(1, countRegisteredFonts(doc.getResManager()));
    }

    private TextObject firstTextObject() {
        List<PageBlockType> blocks = container.getPageBlocks();
        assertEquals(1, blocks.size());
        assertTrue(blocks.get(0) instanceof TextObject);
        return (TextObject) blocks.get(0);
    }

    private int countRegisteredFonts(ResManager resManager) {
        Res publicRes = resManager.pubRes();
        int count = 0;
        for (Fonts fonts : publicRes.getFonts()) {
            for (CT_Font ignored : fonts.getFonts()) {
                count++;
            }
        }
        return count;
    }
}

