public class NamedColorRgbTests {

    /**
     * 断言 {@code input} 的解析结果等于 {@code expected}，失败信息中包含原始输入，便于定位。
     */
    private static void assertRgb(int[] expected, String input) {
        assertArrayEquals(expected, NamedColor.rgb(input), "unexpected RGB for input: [" + input + "]");
    }

    @Test
    @DisplayName("null 输入返回 null")
    void nullInputReturnsNull() {
        assertNull(NamedColor.rgb(null));
    }

    @Test
    @DisplayName("空字符串输入返回 null")
    void emptyStringReturnsNull() {
        assertNull(NamedColor.rgb(""));
    }

    @Test
    @DisplayName("常见命名颜色解析为正确的 RGB 三元组")
    void knownNamedColors() {
        assertRgb(new int[]{0, 0, 0}, "black");
        assertRgb(new int[]{255, 255, 255}, "white");
        assertRgb(new int[]{255, 0, 0}, "red");
        assertRgb(new int[]{0, 128, 0}, "green");
        assertRgb(new int[]{0, 0, 255}, "blue");
        assertRgb(new int[]{0, 255, 255}, "aqua");
        assertRgb(new int[]{127, 255, 212}, "aquamarine");
        assertRgb(new int[]{240, 248, 255}, "aliceblue");
        assertRgb(new int[]{250, 250, 210}, "lightgoldenrodyellow");
        assertRgb(new int[]{154, 205, 50}, "yellowgreen");
        assertRgb(new int[]{208, 32, 144}, "violetred");
        assertRgb(new int[]{209, 146, 117}, "feldspar");
    }

    @Test
    @DisplayName("命名颜色解析与前后的空白、大小写无关")
    void namedColorIsCaseInsensitiveAndTrimmed() {
        assertRgb(new int[]{240, 248, 255}, "AliceBlue");
        assertRgb(new int[]{240, 248, 255}, "ALICEBLUE");
        assertRgb(new int[]{240, 248, 255}, "  aliceBlue  ");
        assertRgb(new int[]{240, 248, 255}, "\taliceblue\n");
        assertRgb(new int[]{0, 0, 128}, "  Navy ");
        assertRgb(new int[]{245, 222, 179}, "WHEAT");
    }

    @Test
    @DisplayName("同义命名颜色返回相同的 RGB 值")
    void synonymousNamedColorsAreEqual() {
