    }

    @Test
    @DisplayName("段内不含居中元素时，居中元素不能加入")
    public void testCenterRejectedInNonCenterSegment() {
        Segment segment = new Segment(100);
        assertTrue(segment.tryAdd(leftFlow(30, 10)), "左浮动元素可加入空段");

        assertFalse(segment.tryAdd(centerFlow(30, 10)), "段内已含非居中元素，居中元素被拒绝");
        assertFalse(segment.isCenterFloat(), "段不是居中布局");
        assertEquals(1, segment.getContent().size(), "段内仍只有 1 个元素");

        Div<Div> accepted = leftFlow(30, 10);
        assertTrue(segment.tryAdd(accepted), "共享元素可以继续加入");
        assertEquals(2, segment.getContent().size(), "段内应有 2 个元素");
    }

    // ---------------------------------------------------------------
    // Float / Clear 组合规则（段内含居中元素）
    // ---------------------------------------------------------------

    @Test
    @DisplayName("居中段内可以继续加入居中元素")
    public void testCenterSegmentAcceptsCenterElements() {
        Segment segment = new Segment(100);
        assertTrue(segment.tryAdd(centerFlow(30, 10)), "居中元素可加入空段");
        assertTrue(segment.isCenterFloat(), "段为居中布局");

        Div<Div> second = centerFlow(30, 10);
        assertTrue(segment.tryAdd(second), "居中元素可以继续加入居中段");
        assertEquals(2, segment.getContent().size(), "段内应有 2 个元素");
        assertSame(second, segment.getContent().get(1), "元素位置正确");
        assertEquals(10d, segment.getHeight(), DELTA, "段高度为元素高度");
    }

    @Test
    @DisplayName("居中段内拒绝非居中元素")
    public void testCenterSegmentRejectsNonCenterElement() {
        Segment segment = new Segment(100);
        assertTrue(segment.tryAdd(centerFlow(30, 10)), "居中元素可加入空段");

        assertFalse(segment.tryAdd(leftFlow(30, 10)), "居中段内拒绝左浮动元素");
        assertEquals(1, segment.getContent().size(), "段内仍只有 1 个元素");

        assertFalse(segment.tryAdd(rightFlow(20, 10)), "居中段内拒绝右浮动元素");
        assertEquals(1, segment.getContent().size(), "段内仍只有 1 个元素");
    }

    @Test
    @DisplayName("居中段内拒绝 clear left 的居中元素")
    public void testCenterSegmentRejectsClearLeftElement() {
        Segment segment = new Segment(100);
        assertTrue(segment.tryAdd(centerFlow(30, 10)), "居中元素可加入空段");

        Div<Div> clearLeft = centerFlow(30, 10);
        clearLeft.setClear(Clear.left);
        assertFalse(segment.tryAdd(clearLeft), "居中段内拒绝 clear left 元素");
        assertEquals(1, segment.getContent().size(), "段内仍只有 1 个元素");
    }

    @Test
    @DisplayName("居中段内最后一个元素 clear right 时拒绝新元素")
    public void testCenterSegmentRejectsWhenLastElementClearsRight() {
        Segment segment = new Segment(100);
        Div<Div> first = centerFlow(30, 10);
        first.setClear(Clear.right);
        assertTrue(segment.tryAdd(first), "空段直接加入居中的 clear right 元素");

        assertFalse(segment.tryAdd(centerFlow(30, 10)), "最后一个元素 clear right 时拒绝新元素");
        assertEquals(1, segment.getContent().size(), "段内仍只有 1 个元素");
        assertEquals(Clear.right, segment.getContent().get(0).getClear(), "段内元素 Clear 未被改变");
    }

    // ---------------------------------------------------------------
    // 其他可观察的副作用
    // ---------------------------------------------------------------

    @Test
    @DisplayName("加入不可拆分元素时段标记为可拆分")
    public void testBlockableFlagUpdatedByAdd() {
        Segment splittable = new Segment(100);
        Div<Div> d1 = div(30, 10);
        d1.setIntegrity(false);
        assertTrue(splittable.tryAdd(d1), "元素可加入");
        assertTrue(splittable.isBlockable(), "出现可拆分元素后段可拆分");

        Segment solid = new Segment(100);
        Div<Div> d2 = div(30, 10);
        d2.setIntegrity(true);
        assertTrue(solid.tryAdd(d2), "元素可加入");
        assertFalse(solid.isBlockable(), "只有一个不可拆分元素时段不可拆分");
    }

    @Test
    @DisplayName("加入页面剩余空间填充元素后段被标记为填充段")
    public void testRemainAreaFillerFlag() {
        Segment segment = new Segment(100);
        PageAreaFiller filler = new PageAreaFiller();

        assertTrue(segment.tryAdd(filler), "填充元素可加入空段");
        assertTrue(segment.isRemainAreaFiller(), "段被标记为剩余空间填充段");
        assertEquals(1, segment.getContent().size(), "段内应含有 1 个元素");
        assertSame(filler, segment.getContent().get(0), "段内元素应为填充元素");
    }

    @Test
    @DisplayName("尺寸未确定的元素按 0 宽处理并被独占加入空段")
    public void testUnSizedBlockElement() {
        Segment segment = new Segment(100);
        Div<Div> unknown = new Div<Div>();
        assertTrue(unknown.isBlockElement(), "默认 Div 为独占元素");

        assertTrue(segment.tryAdd(unknown), "尺寸未确定的独占元素可加入空段");
        assertEquals(1, segment.getContent().size(), "段内应含有 1 个元素");
        assertEquals(0d, segment.getSizeList().get(0).getWidth(), DELTA, "尺寸按 0 记录");
        assertFalse(segment.tryAdd(leftFlow(10, 10)), "独占元素仍占用整段，后续元素不可加入");
    }

    @Test
    @DisplayName("多个元素尺寸序列与内容序列一一对应")
    public void testSizeListMatchesContent() {
        Segment segment = new Segment(120);
        Div<Div> a = leftFlow(20, 10);
        Div<Div> b = rightFlow(30, 25);
        Div<Div> c = leftFlow(40, 5);

        assertTrue(segment.tryAdd(a), "元素 a 可加入");
        assertTrue(segment.tryAdd(b), "元素 b 可加入");
        assertTrue(segment.tryAdd(c), "元素 c 可加入");

        List<Div> content = segment.getContent();
        List<Rectangle> sizes = segment.getSizeList();
        assertEquals(3, content.size(), "段内应有 3 个元素");
        assertEquals(3, sizes.size(), "尺寸序列应有 3 个矩形");
        assertSame(a, content.get(0), "内容顺序与加入顺序一致");
        assertSame(b, content.get(1), "内容顺序与加入顺序一致");
        assertSame(c, content.get(2), "内容顺序与加入顺序一致");
        assertEquals(20d, sizes.get(0).getWidth(), DELTA, "尺寸 a 宽度");
        assertEquals(30d, sizes.get(1).getWidth(), DELTA, "尺寸 b 宽度");
        assertEquals(40d, sizes.get(2).getWidth(), DELTA, "尺寸 c 宽度");
        assertEquals(25d, segment.getHeight(), DELTA, "段高度为最大元素高度");

        assertFalse(segment.tryAdd(leftFlow(40, 10)), "剩余 30 宽不足以容纳 40 宽元素");
        assertEquals(3, content.size(), "被拒绝的元素不进入内容序列");
        assertEquals(3, sizes.size(), "被拒绝的元素不进入尺寸序列");
    }
}

