            assertTrue(pb instanceof PathObject,
                    "Div 渲染只会产生 PathObject，实际为: " + pb.getClass().getName());
            res.add((PathObject) pb);
        }
        return res;
    }

    private static void assertBoundary(PathObject p, double x, double y, double w, double h) {
        ST_Box b = p.getBoundary();
        assertNotNull(b, "图元必须设置外接矩形");
        assertEquals(x, b.getTopLeftX(), DELTA, "外接矩形左上角X");
        assertEquals(y, b.getTopLeftY(), DELTA, "外接矩形左上角Y");
        assertEquals(w, b.getWidth(), DELTA, "外接矩形宽度");
        assertEquals(h, b.getHeight(), DELTA, "外接矩形高度");
