    private static void assertRectPath(PathObject p, double x, double y, double w, double h) {
        LinkedList<OptVal> ops = ops(p);
        assertEquals(5, ops.size(), "矩形轮廓应包含 M、3个 L 与 C 共5个操作");
        assertEquals("M", ops.get(0).getOpt());
        assertArrayEquals(new double[]{x, y}, ops.get(0).getValues(), DELTA, "矩形起点");
        assertEquals("L", ops.get(1).getOpt());
        assertArrayEquals(new double[]{x + w, y}, ops.get(1).getValues(), DELTA, "矩形右上角");
        assertEquals("L", ops.get(2).getOpt());
        assertArrayEquals(new double[]{x + w, y + h}, ops.get(2).getValues(), DELTA, "矩形右下角");
        assertEquals("L", ops.get(3).getOpt());
        assertArrayEquals(new double[]{x, y + h}, ops.get(3).getValues(), DELTA, "矩形左下角");
        assertEquals("C", ops.get(4).getOpt());
    }

    private static void assertLinePath(PathObject p, double fromX, double fromY, double toX, double toY) {
        LinkedList<OptVal> ops = ops(p);
