        assertEquals("M", ops.get(0).getOpt());
        assertArrayEquals(new double[]{fromX, fromY}, ops.get(0).getValues(), DELTA, "线条起点");
        assertEquals("L", ops.get(1).getOpt());
        assertArrayEquals(new double[]{toX, toY}, ops.get(1).getValues(), DELTA, "线条终点");
    }

    private static String rgb(PathObject p, boolean fill) {
