    }

    @Test
    @DisplayName("无背景色且无边框：即使高度未指定也不抛异常（先返回）")
    void noBackgroundAndNoBorderWithoutHeight_doesNotThrow() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(7);
        Div<?> e = new Div();
        e.setWidth(100d);

        DivRender.render(layer, e, maxUnitID);

        assertTrue(layer.getPageBlocks().isEmpty());
        assertEquals(7, maxUnitID.get());
    }

    @Test
    @DisplayName("存在背景色但高度为null：抛出IllegalArgumentException且不绘制")
    void nullHeightWithBackground_throwsIllegalArgumentException() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(1);
