    void nullHeightWithBorder_throwsIllegalArgumentException() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(1);
        Div<?> e = new Div();
        e.setX(0d);
        e.setY(0d);
        e.setWidth(100d);
        e.setBorder(1d);

        assertThrows(IllegalArgumentException.class, () -> DivRender.render(layer, e, maxUnitID));
        assertTrue(layer.getPageBlocks().isEmpty());
        assertEquals(1, maxUnitID.get());
    }

    /* ------------------------------------------------------------------ 背景绘制 */

    @Test
    @DisplayName("仅有背景色、无边框：绘制背景矩形，同时等宽分支绘制零宽边框")
    void backgroundOnly_drawsBackgroundAndZeroWidthBorder() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(0);
