    @Test
    @DisplayName("单个Span被渲染为一个文字对象，包含边界、字体、字号与文字定位信息")
    void render_singleSpan_createsTextObject() {
        Paragraph paragraph = newParagraph(50d);
        paragraph.add(new Span(font, FONT_SIZE, "AB"));

        ParagraphRender.render(layer, resManager, paragraph, maxUnitID);

        List<TextObject> texts = textObjects(layer);
        assertEquals(1, texts.size(), "一行一个Span应只产生一个文字对象");

        TextObject txt = texts.get(0);
        ST_Box box = txt.getBoundary();
        assertNotNull(box);
        assertEquals(0d, box.getTopLeftX(), EPS, "无外边距/边框/内边距时行起始X为元素X");
        assertEquals(0d, box.getTopLeftY(), EPS, "首个行块的Y为元素Y");
        assertEquals(2 * FONT_SIZE, box.getWidth(), EPS, "文字对象宽度为Span内容宽度");
        assertEquals(LINE_HEIGHT, box.getHeight(), EPS, "文字对象高度为整行高度");

        assertEquals(FONT_SIZE, txt.getSize(), EPS, "文字对象字号应来自Span");

        // 字体资源被注册并引用
        assertEquals(1, resManager.getNewResIds().size(), "Span字体应被注册到资源管理器");
        ST_ID fontId = resManager.getNewResIds().get(0);
        assertNotNull(txt.getFont(), "文字对象应引用字体资源");
        assertEquals(fontId.getId(), txt.getFont().getRefId().getId(), "文字对象应引用已注册的字体资源");

        // 文字内容与定位点
        List<TextCode> codes = txt.getTextCodes();
        assertEquals(1, codes.size(), "一个Span只包含一个TextCode");
        TextCode code = codes.get(0);
        assertEquals("AB", code.getContent(), "TextCode内容为Span文字");
        assertEquals(0d, code.getX(), EPS, "TextCode的X偏移为0");
        assertEquals(FONT_SIZE, code.getY(), EPS, "TextCode的Y偏移为行内最高字符高度");
        Double[] deltaX = code.getDeltaX().toDouble();
        assertEquals(1, deltaX.length, "2个字符应只有1个字符偏移量");
        assertEquals(FONT_SIZE, deltaX[0], EPS, "字符偏移量为字符宽度");

        // 未设置的样式使用默认值
        assertEquals(Weight.W_400, txt.getWeight(), "未设置粗细时使用默认粗细400");
        assertFalse(txt.getItalic(), "默认不是斜体");
        assertTrue(txt.getFill(), "默认填充");
        assertNull(txt.getFillColor(), "默认颜色为黑色（不写入FillColor）");
        assertEquals(Integer.valueOf(255), txt.getAlpha(), "默认不透明");
    }

