    @Test
    @DisplayName("带有下划线的Span额外渲染一条路径对象（默认线宽为字号的0.05倍）")
    void render_underline_createsPathObject() {
        Paragraph paragraph = newParagraph(50d);
        paragraph.add(new Span(font, FONT_SIZE, "A")
                .setUnderline(true)
                .setColor(0, 0, 255));

        ParagraphRender.render(layer, resManager, paragraph, maxUnitID);

        List<PageBlockType> blocks = layer.getPageBlocks();
        assertEquals(2, blocks.size(), "下划线应额外产生一个路径对象");
        assertTrue(blocks.get(0) instanceof TextObject, "文字对象先于下划线加入图层");
        assertTrue(blocks.get(1) instanceof PathObject, "文字对象之后加入下划线路径");

        TextObject txt = (TextObject) blocks.get(0);
        PathObject underline = (PathObject) blocks.get(1);

        assertEquals(txt.getBoundary().getWidth(), underline.getBoundary().getWidth(), EPS,
                "下划线宽度与文字对象宽度一致");
        assertEquals(txt.getBoundary().getHeight(), underline.getBoundary().getHeight(), EPS,
                "下划线区域与文字对象区域一致");
        assertEquals(FONT_SIZE * 0.05, underline.getLineWidth(), EPS,
                "下划线线宽默认为字号的0.05倍");
        assertNotNull(underline.getStrokeColor(), "下划线应使用Span颜色作为描边颜色");
        assertArrayEquals(new Integer[]{0, 0, 255}, underline.getStrokeColor().getValue().toInt());

        LinkedList<OptVal> path = underline.getAbbreviatedDataEle().getRawOptVal();
        assertEquals(2, path.size(), "下划线由移动与连线两个操作符组成");
        assertEquals("M", path.get(0).getOpt());
        assertEquals(0d, path.get(0).getValues()[0], EPS);
        assertEquals(FONT_SIZE + 1.2d, path.get(0).getValues()[1], EPS,
                "下划线的Y偏移 = 行内最高字符高度 + 下划线偏移量(默认1.2)");
        assertEquals("L", path.get(1).getOpt());
        assertEquals(FONT_SIZE, path.get(1).getValues()[0], EPS, "下划线终点X为文字对象宽度");
        assertEquals(FONT_SIZE + 1.2d, path.get(1).getValues()[1], EPS);
    }

