    @Test
    @DisplayName("行高由行内最高字符决定，后续行的Y坐标按各行实际高度累加")
    void render_mixedLineHeights_accumulateActualLineHeights() {
        Span small = new Span(font, FONT_SIZE, "A");
        Span big = new Span(font, 2 * FONT_SIZE, "B").setLinebreak(true);
        Span next = new Span(font, FONT_SIZE, "C");

        Paragraph paragraph = newParagraph(100d);
        paragraph.add(small).add(big).add(next);

        ParagraphRender.render(layer, resManager, paragraph, maxUnitID);

        LinkedList<TxtLineBlock> lines = paragraph.getLines();
        assertEquals(2, lines.size(), "linebreak 的Span之后另起一行");
        assertEquals(2 * FONT_SIZE + 2d, lines.get(0).getHeight(), EPS, "首行行高由最高字符决定");
        assertEquals(FONT_SIZE + 2d, lines.get(1).getHeight(), EPS);

        List<TextObject> texts = textObjects(layer);
        assertEquals(3, texts.size());
        // 首行两个文字对象的区域高度为行高，且Y相同
        assertEquals(2 * FONT_SIZE + 2d, texts.get(0).getBoundary().getHeight(), EPS);
        assertEquals(2 * FONT_SIZE + 2d, texts.get(1).getBoundary().getHeight(), EPS);
        assertEquals(0d, texts.get(0).getBoundary().getTopLeftY(), EPS);
        assertEquals(0d, texts.get(1).getBoundary().getTopLeftY(), EPS);
        // 第二行Y为第一行行高
        assertEquals(2 * FONT_SIZE + 2d, texts.get(2).getBoundary().getTopLeftY(), EPS);
        assertEquals(FONT_SIZE + 2d, texts.get(2).getBoundary().getHeight(), EPS);
        // 行内TextCode的Y偏移为该行最高字符高度
        assertEquals(2 * FONT_SIZE, texts.get(0).getTextCodes().get(0).getY(), EPS);
        assertEquals(2 * FONT_SIZE, texts.get(1).getTextCodes().get(0).getY(), EPS);
        assertEquals(FONT_SIZE, texts.get(2).getTextCodes().get(0).getY(), EPS);
    }

