        paragraph.add(new Span(font, FONT_SIZE, "A"));

        RenderException ex = assertThrows(RenderException.class,
                () -> ParagraphRender.render(layer, failing, paragraph, new AtomicInteger(100)));

        assertTrue(ex.getMessage().contains("字体复制失败"), "异常信息应说明字体复制失败：" + ex.getMessage());
