    // 辅助方法
    // ------------------------------------------------------------------

    /**
     * 构造一个指定内容宽度的段落，并显式设置绝对定位坐标。
     * <p>
     * 渲染器需要读取元素的 X、Y 坐标，未设置坐标的元素无法参与渲染。
     *
     * @param width 内容宽度
     * @return 段落对象
     */
    private static Paragraph newParagraph(double width) {
        return new Paragraph().setX(0d).setY(0d).setWidth(width);
    }

    /**
     * 构造一个所有可打印ASCII字符宽度占比均为 1 的字体。
     * <p>
     * 该字体没有字体文件，字符宽度 = 字号 * 占比，因此与系统字体无关，结果确定。
     *
     * @param name 字体名称
     * @return 测试字体
     */
    private static Font uniformWidthFont(String name) {
        double[] map = new double[95];
        for (int i = 0; i < map.length; i++) {
            map[i] = 1.0d;
        }
        return new Font(name, name, null, map);
    }

    /**
     * 渲染只包含一个 "AB" Span 的段落，并返回首字符的X坐标
     *
     * @param align 对齐方式
     * @return 首字符X坐标
     */
    private double renderedTextX(TextAlign align) {
        CT_PageBlock block = new CT_PageBlock();
        Paragraph paragraph = newParagraph(50d);
        paragraph.setTextAlign(align);
        paragraph.add(new Span(font, FONT_SIZE, "AB"));

        ParagraphRender.render(block, resManager, paragraph, new AtomicInteger(100));

        List<TextObject> texts = textObjects(block);
        assertEquals(1, texts.size(), "对齐测试应只产生一个文字对象");
        return texts.get(0).getBoundary().getTopLeftX();
    }

    /**
     * 构造一个宽度25、内容为"AAAAA"（每行2字符，共3行）的段落。
     *
     * @param height 段落高度，null表示不显式设置高度
     * @return 段落对象
     */
    private static Paragraph wrappedParagraph(Double height) {
        Paragraph paragraph = newParagraph(25d);
        if (height != null) {
            paragraph.setHeight(height);
        }
        paragraph.add(new Span(uniformWidthFont("OFDRW-Test-Font"), FONT_SIZE, "AAAAA"));
        return paragraph;
    }

    /**
     * 从图层中取出所有文字对象（按加入顺序）
     *
     * @param block 图层
     * @return 文字对象列表
     */
    private static List<TextObject> textObjects(CT_PageBlock block) {
        List<TextObject> res = new ArrayList<>();
        for (PageBlockType pb : block.getPageBlocks()) {
            if (pb instanceof TextObject) {
                res.add((TextObject) pb);
            }
        }
        return res;
    }
}

