        CT_DrawParam self = registerParam(1L, 1L);
        self.setLineWidth(4.0);

        List<String> visited = new ArrayList<>();
        CT_DrawParam result = resourceManage.superDrawParam(self, visited);

        assertNotNull(result);
        // Id 1 is added before the recursive lookup, so the recursive lookup sees the cycle
        // and returns an unresolved copy. The outer call can then inherit from that copy.
        assertEquals(self.attributeValue("LineWidth"), result.attributeValue("LineWidth"));
        assertTrue(visited.isEmpty());
    }

    @Test
    @DisplayName("a multi-node cycle terminates and keeps the visited path consistent")
    void multiNodeCycleTerminates() {
        CT_DrawParam a = registerParam(1L, 2L);
        a.setLineWidth(4.0);
        CT_DrawParam b = registerParam(2L, 1L);

        List<String> visited = new ArrayList<>();
        CT_DrawParam result = resourceManage.superDrawParam(a, visited);

        assertNotNull(result);
        assertEquals(a.attributeValue("LineWidth"), result.attributeValue("LineWidth"));
        assertTrue(visited.isEmpty());
    }
}

