    @Test
    void keywordSplitAcrossThreeTextCodes_isMergedIntoOnePosition() throws Exception {
        Path ofd = writeOfd("splitThree.ofd",
                textObject(6, "57.16 170.84 8.47 7.81", "4.0", "4 4", "重庆")
                        + textObject(7, "65.63 170.84 12.70 7.81", "4.0", "4 4 4", "市马上")
                        + textObject(8, "78.33 170.84 21.17 7.81", "4.0", "4 4 4 4", "融资担保")
