    public List<StampAnnot> getAppearance(OFDReader ctx, SignIDProvider idProvider) {
        // 总页码数
        int numPage = ctx.getNumberOfPages();
        List<StampAnnot> res = new ArrayList<>(numPage);
        if (side == Side.Right) {
            double itemWith = this.width * 0.5;
