    /**
     * 页面未定义 Area 时使用文档 CommonData 中的默认页面区域计算尺寸，
     * 而定义了 Area 的页面使用自身尺寸。
     */
    @Test
    void pageWithoutAreaUsesDocumentDefaultPageArea(@TempDir Path tempDir) throws IOException {
        double[][] sizes = new double[2][];
        sizes[0] = null;                      // 第1页不定义 Area -> 使用文档默认 300x400
        sizes[1] = new double[]{250d, 350d};  // 第2页定义自己的 Area
        Path ofd = buildOfd(tempDir, sizes);
        CountingIDProvider idProvider = new CountingIDProvider();
        // width=100, height=50, margin=0, offset=null
        CuttingRideStampPos pos = new CuttingRideStampPos(Side.Right, null, 100d, 50d, 0d, null);

        List<StampAnnot> res;
        try (OFDReader ctx = new OFDReader(ofd)) {
            res = pos.getAppearance(ctx, idProvider);
        }

        assertEquals(2, res.size());
