        assertBoundary(res.get(0), 250d, 175d, 100d, 50d);
        assertClip(res.get(0), 0d, 0d, 50d, 50d);
        // 第2页（末页 250x350）：x = -(100 - 50) = -50；y = 175 - 25 = 150
        assertBoundary(res.get(1), -50d, 150d, 100d, 50d);
        assertClip(res.get(1), 50d, 0d, 50d, 50d);
    }

    /**
