        CountingIDProvider idProvider = new CountingIDProvider();

        List<StampAnnot> topRes;
        List<StampAnnot> bottomRes;
        try (OFDReader ctx = new OFDReader(ofd)) {
            topRes = new CuttingRideStampPos(Side.Top, null, 100d, 40d, 0d, null)
                    .getAppearance(ctx, idProvider);
            bottomRes = new CuttingRideStampPos(Side.Bottom, null, 100d, 40d, 0d, null)
                    .getAppearance(ctx, idProvider);
        }

        assertNotNull(topRes);
        assertTrue(topRes.isEmpty(), "Top 方向不应产生签章外观");
        assertNotNull(bottomRes);
        assertTrue(bottomRes.isEmpty(), "Bottom 方向不应产生签章外观");
        assertEquals("s000", idProvider.get(), "未产生外观时不应消耗签名ID");
    }

    /**
     * 每页页面大小不同时，x / y 分别基于所在页面的尺寸计算。
     */
    @Test
    void perPageSizesAreUsedForEachPage(@TempDir Path tempDir) throws IOException {
        double[][] sizes = new double[][]{
                {400d, 100d},
                {200d, 300d},
                {300d, 500d}
        };
        Path ofd = buildOfd(tempDir, sizes);
        CountingIDProvider idProvider = new CountingIDProvider();
        CuttingRideStampPos pos = new CuttingRideStampPos(Side.Right, null, 100d, 40d, 0d, null);

        List<StampAnnot> res;
        try (OFDReader ctx = new OFDReader(ofd)) {
            res = pos.getAppearance(ctx, idProvider);
        }

        assertEquals(4, res.size());
        // 第1页 400x100：x = 400 - 50 = 350，y = 50 - 20 = 30
        assertBoundary(res.get(0), 350d, 30d, 100d, 40d);
        // 第2页 200x300：x = 200 - 50 = 150，y = 150 - 20 = 130
        assertBoundary(res.get(1), 150d, 130d, 100d, 40d);
        // 第2页回折：x = -(100 - 50) = -50, y 同页 = 130
        assertBoundary(res.get(2), -50d, 130d, 100d, 40d);
        // 第3页（末页）300x500：x = -50, y = 250 - 20 = 230
        assertBoundary(res.get(3), -50d, 230d, 100d, 40d);
    }

    /**
     * 只给 1 页却提供了 cuttingRatios 时，末页分支会访问 ratios[i-1] = ratios[-1]，
     * 因此抛出 IndexOutOfBoundsException（当前实现的既有行为）。
     */
    @Test
    void singlePageWithCuttingRatiosThrowsIndexOutOfBounds(@TempDir Path tempDir) throws IOException {
        Path ofd = buildOfd(tempDir, 1, 500d, 200d);
        CountingIDProvider idProvider = new CountingIDProvider();
        List<CuttingRatio> ratios = Arrays.asList(ratio(0.3, 0.7));
        CuttingRideStampPos pos = new CuttingRideStampPos(Side.Right, null, 100d, 40d, 0d, ratios);

        try (OFDReader ctx = new OFDReader(ofd)) {
            assertThrows(IndexOutOfBoundsException.class, () -> pos.getAppearance(ctx, idProvider));
        }
    }

    /**
     * 多个骑缝章共享同一 ID 提供器时，ID 连续递增且不与已有 ID 冲突。
     */
    @Test
    void idsContinueFromProvidedMaxSignId(@TempDir Path tempDir) throws IOException {
        Path ofd = buildOfd(tempDir, 2, 500d, 200d);
        CountingIDProvider idProvider = new CountingIDProvider();
        idProvider.setCurrentMaxSignId("s007");
        CuttingRideStampPos pos = new CuttingRideStampPos(Side.Left, null, 100d, 40d, 0d, null);

        List<StampAnnot> res;
        try (OFDReader ctx = new OFDReader(ofd)) {
            res = pos.getAppearance(ctx, idProvider);
        }

        assertEquals(2, res.size());
        assertId(res.get(0), "s008");
        assertId(res.get(1), "s009");
        assertEquals("s009", idProvider.get(), "ID 提供器最终状态应为最后一次分配的ID");
    }

    /**
     * 返回的列表应按照页码顺序、且裁剪区域与边界宽度一致（右半 + 左半 = 整章宽度）。
     */
    @Test
    void clipWidthsAndBoundaryWidthsAreConsistent(@TempDir Path tempDir) throws IOException {
        Path ofd = buildOfd(tempDir, 3, 400d, 250d);
        CountingIDProvider idProvider = new CountingIDProvider();
        CuttingRideStampPos pos = new CuttingRideStampPos(Side.Right, null, 120d, 60d, 0d, null);

        List<StampAnnot> res;
        try (OFDReader ctx = new OFDReader(ofd)) {
            res = pos.getAppearance(ctx, idProvider);
        }

        assertEquals(4, res.size());
        for (StampAnnot annot : res) {
            assertNotNull(annot.getBoundary());
            assertEquals(120d, annot.getBoundary().getWidth(), 1e-6);
            assertEquals(60d, annot.getBoundary().getHeight(), 1e-6);
            assertNotNull(annot.getClip());
            assertEquals(60d, annot.getClip().getWidth(), 1e-6, "裁剪宽度应为整章宽度的一半");
            assertEquals(60d, annot.getClip().getHeight(), 1e-6);
        }
    }
}

