    // 工具方法
    // ------------------------------------------------------------------

    /**
     * 构建并打开一个包含指定页面尺寸的 OFD 文档，页面对象ID依次为 100、101、...
     *
     * @param pageSizes 每页的物理尺寸（宽、高），单位毫米
     * @return 已打开的OFD解析器
     */
    private OFDReader reader(double[]... pageSizes) throws IOException {
        long[] ids = new long[pageSizes.length];
        for (int i = 0; i < ids.length; i++) {
            ids[i] = 100L + i;
        }
        return readerWithIds(pageSizes, ids);
    }

    /**
     * 构建并打开一个包含指定页面尺寸与页面对象ID的 OFD 文档
     *
     * @param pageSizes 每页的物理尺寸（宽、高），单位毫米
     * @param pageIds   每页的页面对象ID
     * @return 已打开的OFD解析器
     */
    private OFDReader readerWithIds(double[][] pageSizes, long[] pageIds) throws IOException {
        Path ofdFile = workDir.resolve("test-" + (fileIndex++) + ".ofd");
        OFDDir ofdDir = OFDDir.newOFD();
        try {
            DocDir docDir = ofdDir.newDoc();
            PagesDir pagesDir = docDir.obtainPages();
            Pages pages = new Pages();
            for (int i = 0; i < pageSizes.length; i++) {
                PageDir pageDir = pagesDir.newPageDir();
                org.ofdrw.core.basicStructure.pageObj.Page content =
                        new org.ofdrw.core.basicStructure.pageObj.Page();
                content.setArea(new CT_PageArea(0, 0, pageSizes[i][0], pageSizes[i][1]));
                pageDir.setContent(content);
                pages.addPage(new org.ofdrw.core.basicStructure.pageTree.Page(
                        pageIds[i], "Pages/" + pageDir.getContainerName() + "/Content.xml"));
            }
            Document document = new Document();
            document.setCommonData(new CT_CommonData().setPageArea(new CT_PageArea(0, 0, 210, 297)));
            document.setPages(pages);
            docDir.setDocument(document);
            ofdDir.setOfd(new OFD().addDocBody(
                    new DocBody().setDocRoot(new ST_Loc(docDir.getContainerName() + "/Document.xml"))));
            ofdDir.jar(ofdFile);
        } finally {
            ofdDir.clean();
        }
        OFDReader reader = new OFDReader(ofdFile);
        readers.add(reader);
        return reader;
    }

    /**
     * 校验矩形区域四个坐标值
     */
    private static void assertBox(String label, ST_Box actual, double x, double y, double width, double height) {
        assertNotNull(actual, label + "不应为空");
        assertEquals(x, actual.getTopLeftX().doubleValue(), DELTA, label + " 横坐标");
        assertEquals(y, actual.getTopLeftY().doubleValue(), DELTA, label + " 纵坐标");
        assertEquals(width, actual.getWidth().doubleValue(), DELTA, label + " 宽度");
        assertEquals(height, actual.getHeight().doubleValue(), DELTA, label + " 高度");
    }
}
